import { getState } from '../state.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { eventStartYear } from '../data/spans.ts';
import { jumpToStoryStep, storyCheckpoints } from '../story/controls.ts';

export function lensCheckpoints(events: readonly HistoricalEvent[], chooseYear: (year: number) => void) {
  const eventYears = new Set(events.map(eventStartYear));
  return {
    checkpoints: () => {
      const { story, threadEvents, activeCategories } = getState();
      if (story) return new Set(storyCheckpoints(story.id).map(point => point.year));
      if (!threadEvents && !activeCategories.size) return eventYears;
      const ids = threadEvents ? new Set(threadEvents) : null;
      return new Set(events.filter(e => (!ids || ids.has(e.id)) && (!activeCategories.size || activeCategories.has(e.category))).map(eventStartYear));
    },
    onFineCommit: (year: number) => {
      const story = getState().story;
      if (!story) { chooseYear(year); return; }
      const hits = storyCheckpoints(story.id).filter(p => p.year === year);
      const closest = hits.sort((a, b) => Math.abs(a.step - story.step) - Math.abs(b.step - story.step))[0];
      if (closest && closest.step !== story.step) jumpToStoryStep(closest.step);
    },
  };
}
