import { formatEventDate } from '../data/format.ts';
import { addStopPreview } from './stopPreview.ts';
import { eventStartYear } from '../data/spans.ts';
import type { HistoricalEvent } from '../data/types.ts';
import type { ResolvedPath } from '../data/pathTypes.ts';
import { el } from '../dom.ts';
import { ESCAPE_PRIORITY, registerEscape } from '../escape.ts';
import { byDate } from '../panel/siblings.ts';
import { getState, setState, subscribe } from '../state.ts';
import { dismissScene, openScene } from './navigate.ts';
import { createSceneCard, sceneControl } from './sceneCard.ts';
import { groupDate, groupStops } from './sceneStops.ts';
import type { StopGroup } from './sceneStops.ts';
import type { Scale } from './scale.ts';

export function createCheckpointRail(events: readonly HistoricalEvent[], paths: readonly ResolvedPath[], getScale: () => Scale) {
  const rail = el('div', 'scene-rail');
  const track = el('div', 'scene-rail__track');
  const dots = el('div', 'scene-rail__stops');
  dots.setAttribute('role', 'group');
  dots.setAttribute('aria-label', 'Timeline');
  const tether = el('span', 'scene-rail__leader');
  tether.setAttribute('aria-hidden', 'true'); tether.hidden = true;
  const picker = el('section', 'rail-popover scene-picker');
  picker.setAttribute('aria-labelledby', 'scene-picker-title');
  picker.hidden = true;
  const label = el('h2'); label.id = 'scene-picker-title';
  const list = el('div', 'scene-picker__list');
  const head = el('div', 'scene-picker__head');
  head.append(label, sceneControl('Close', 'close', () => closePicker(true)));
  picker.append(head, list);
  const ordered = [...events].sort(byDate);
  let visible: HistoricalEvent[] = [], groups: StopGroup[] = [];
  let current: HistoricalEvent | undefined;
  let group: StopGroup | null = null;
  let opener: HTMLElement | null = null;
  const card = createSceneCard({
    close: dismissScene, details: () => setState({ eventView: 'scene-details' }),
    step(by) {
      const index = visible.findIndex(e => e.id === current?.id);
      const next = visible[index + by];
      if (next) openScene(next);
    },
  });
  track.append(dots, tether, picker, card.element); rail.append(track);
  const clearPreview = addStopPreview(track, dots, id => groups.find(g => g.events[0]?.id === id),
    () => !rail.hidden && card.element.hidden && picker.hidden && !getState().isScrubbing && !getState().isPlaying);

  function buttonFor(id?: string): HTMLButtonElement | undefined {
    const index = groups.findIndex(g => g.events.some(e => e.id === id));
    return dots.querySelectorAll('button')[index];
  }
  function closePicker(focus: boolean): void {
    if (!group) return;
    const anchor = buttonFor(group.events[0]?.id);
    group = null; picker.hidden = true;
    anchor?.setAttribute('aria-expanded', 'false');
    if (current && getState().eventView === 'scene') card.element.hidden = false;
    position();
    if (focus) anchor?.focus({ preventScroll: true });
  }
  function position(): void {
    const sceneOpen = !card.element.hidden;
    const pos = group?.position ?? (sceneOpen && current ? getScale().yearToPosition(eventStartYear(current)) : null);
    tether.hidden = pos === null;
    if (pos === null) return;
    const w = track.clientWidth, panel = group ? picker : card.element;
    const half = panel.offsetWidth / 2;
    const anchor = pos * w;
    let left = Math.max(-8, Math.min(w - half * 2 + 8, anchor - half));
    if (matchMedia('(max-height: 540px) and (min-aspect-ratio: 4/3)').matches) {
      // Place the inset to one side so the full height beside it still belongs to the map.
      const origin = track.getBoundingClientRect().left;
      left = (origin + anchor < innerWidth / 2 ? 10 : innerWidth - 54 - half * 2) - origin;
    }
    panel.style.left = left + 'px';
    tether.style.left = anchor + 'px';
    const landing = Math.max(left + 14, Math.min(left + half * 2 - 14, anchor));
    tether.style.setProperty('--leader-offset', Math.min(0, landing - anchor) + 'px');
    tether.style.setProperty('--leader-span', Math.abs(landing - anchor) + 'px');
  }
  function choose(g: StopGroup, button: HTMLButtonElement): void {
    clearPreview();
    if (group === g) { closePicker(true); return; }
    closePicker(false);
    opener = button;
    const first = g.events[0];
    if (!first) return;
    if (g.events.length === 1) { openScene(first); return; }
    group = g; label.textContent = groupDate(g.events);
    button.setAttribute('aria-expanded', 'true');
    list.replaceChildren(...g.events.map(event => {
      const item = el('button', 'scene-picker__item'); item.type = 'button'; item.dataset.event = event.id;
      item.append(el('span', 'scene-picker__date', formatEventDate(event)), el('span', '', event.title));
      item.addEventListener('click', () => { closePicker(false); openScene(event); });
      return item;
    }));
    card.element.hidden = true;
    picker.hidden = false; list.scrollTop = 0; position();
    list.querySelector('button')?.focus({ preventScroll: true });
  }

  function focusKey(e: KeyboardEvent, parent: HTMLElement, keys: readonly string[]): void {
    if (!(e.target instanceof HTMLButtonElement)) return;
    const buttons = [...parent.querySelectorAll('button')];
    const index = buttons.indexOf(e.target);
    if (index < 0) return;
    const i = e.key === 'Home' ? 0 : e.key === 'End' ? buttons.length - 1 :
      e.key === keys[0] ? index - 1 : e.key === keys[1] ? index + 1 : null;
    if (i === null) return;
    e.preventDefault(); e.stopPropagation();
    buttons[Math.max(0, Math.min(buttons.length - 1, i))]?.focus();
  }
  dots.addEventListener('keydown', e => focusKey(e, dots, ['ArrowLeft', 'ArrowRight']));
  list.addEventListener('keydown', e => focusKey(e, list, ['ArrowUp', 'ArrowDown']));
  dots.addEventListener('focusin', e => {
    for (const b of dots.querySelectorAll('button')) b.tabIndex = b === e.target ? 0 : -1;
  });
  document.addEventListener('pointerdown', e => {
    if (group && e.target instanceof Node && !track.contains(e.target)) closePicker(false);
  }, { capture: true, passive: true });
  registerEscape({ priority: ESCAPE_PRIORITY.filters + .4, isOpen: () => Boolean(group) || getState().eventView === 'scene',
    close: () => group ? closePicker(true) : dismissScene() });

  function update(): void {
    clearPreview();
    const state = getState(), scale = getScale();
    const width = track.clientWidth;
    rail.hidden = !!state.story;
    const focus = document.activeElement;
    const focusId = focus instanceof HTMLElement && dots.contains(focus) ? focus.dataset.first : undefined;
    closePicker(false);
    visible = ordered.filter(e => {
      const year = eventStartYear(e);
      return year >= scale.minYear && year <= scale.maxYear &&
        (!state.activeCategories.size || state.activeCategories.has(e.category)) &&
        (!state.threadEvents || state.threadEvents.includes(e.id));
    });
    groups = groupStops(visible, scale, width, window.matchMedia('(pointer: coarse)').matches || width < 560 ? 39 : 31);
    dots.replaceChildren(...groups.map((g, i) => {
      const button = el('button', 'scene-stop'); button.type = 'button'; button.tabIndex = i === 0 ? 0 : -1;
      button.style.left = (g.position * 100) + '%';
      button.dataset.first = g.events[0]!.id;
      const many = g.events.length > 1;
      if (many) { button.dataset.group = ''; button.setAttribute('aria-expanded', 'false'); }
      const value = many ? groupDate(g.events) + ' · ' + g.events.length : groupDate(g.events) + ' · ' + g.events[0]!.title;
      button.setAttribute('aria-label', value);
      const bead = el('span', 'scene-stop__bead', many ? String(g.events.length) : '');
      bead.setAttribute('aria-hidden', 'true'); button.append(bead);
      button.addEventListener('click', () => choose(g, button));
      return button;
    }));
    if (focusId) buttonFor(focusId)?.focus({ preventScroll: true });
    markCurrent();
    position();
  }
  function markCurrent(): void {
    dots.querySelector('[aria-current]')?.removeAttribute('aria-current');
    buttonFor(getState().selectedEventId ?? undefined)?.setAttribute('aria-current', 'step');
    const i = current ? visible.findIndex(e => e.id === current?.id) : -1;
    card.back.disabled = i <= 0; card.next.disabled = i < 0 || i >= visible.length - 1;
  }
  function sync(): void {
    clearPreview();
    const state = getState(), previous = current;
    const active = document.activeElement;
    closePicker(false);
    current = state.eventView === 'scene' ? ordered.find(e => e.id === state.selectedEventId) : undefined;
    document.documentElement.toggleAttribute('data-event-scene', !!current);
    if (current) {
      if (active instanceof HTMLElement && active.closest('.era-entries')) opener = active;
      const id = current.id;
      card.show(current, paths.filter(p => p.eventId === id));
      markCurrent(); position();
      if (active !== card.next && active !== card.back || (active instanceof HTMLButtonElement && active.disabled)) {
        card.heading.focus({ preventScroll: true });
      }
    } else {
      const restore = previous && !state.story && !state.selectedEventId && !state.selectedPlaceId && card.element.contains(active);
      card.element.hidden = true; markCurrent(); position();
      if (restore) (opener?.getClientRects().length ? opener : buttonFor(previous.id))?.focus({ preventScroll: true });
    }
  }
  let width = -1;
  new ResizeObserver(() => {
    if (width !== track.clientWidth) { width = track.clientWidth; update(); }
  }).observe(track);
  const reposition = new ResizeObserver(position);
  reposition.observe(card.element); reposition.observe(picker);
  window.addEventListener('resize', position, { passive: true });
  subscribe((s, prev) => {
    if (s.isScrubbing || s.isPlaying) clearPreview();
    if (s.activeCategories !== prev.activeCategories || s.threadEvents !== prev.threadEvents || s.story !== prev.story) update();
    if (s.selectedEventId !== prev.selectedEventId || s.eventView !== prev.eventView || s.story !== prev.story) sync();
  });
  update(); sync();
  function chooseYear(year: number): void {
    const matches = visible.filter(e => eventStartYear(e) === year);
    const anchor = buttonFor(matches[0]?.id);
    if (!anchor || !matches.length) return;
    choose({ position: getScale().yearToPosition(year), events: matches }, anchor);
  }
  return { element: rail, update, chooseYear };
}
