import type { Scale } from './scale.ts';
import type { createScrubLens } from './scrubLens.ts';

interface Scrubber {
  scale(): Scale;
  onInput(year: number): void;
  onUserControl(): void;
  onScrubChange(on: boolean): void;
  onFineCommit(year: number): void;
}

export function attachScrubGesture(surface: HTMLElement, track: HTMLElement, inner: HTMLElement, handle: HTMLElement,
  lens: ReturnType<typeof createScrubLens>, options: Scrubber) {
  let pointer: number | null = null;
  let started = false, precise = false, startX = 0, startY = 0, x = 0, year = 0;
  let frame = 0, hold = 0;
  let mark: HTMLElement | null = null, suppress: HTMLElement | null = null;
  let rect: DOMRect;

  function ordinary(clientX: number): number {
    return options.scale().positionToYear((clientX - rect.left) / Math.max(1, rect.width));
  }
  function begin(): void {
    if (started) return;
    started = true;
    if (pointer !== null) surface.setPointerCapture(pointer);
    year = mark?.dataset.year ? Number(mark.dataset.year) : ordinary(startX);
    handle.focus({ preventScroll: true });
    options.onUserControl();
    options.onScrubChange(true);
    track.classList.add('is-dragging');
    lens.begin(year, startX);
    options.onInput(year);
    if (mark) suppress = mark;
  }
  function lock(): void {
    begin();
    lens.lock(year, x);
    precise = true;
  }
  function flush(): void {
    frame = 0;
    year = lens.yearAt(x) ?? ordinary(x);
    options.onInput(year);
    lens.show(year, x);
  }
  surface.addEventListener('pointerdown', e => {
    if (e.button !== 0 || !e.isPrimary || pointer !== null || !(e.target instanceof Element)) return;
    if (!e.target.closest('.track,.scene-stop') || e.target.closest('.rail-popover')) return;
    pointer = e.pointerId;
    startX = x = e.clientX; startY = e.clientY;
    rect = inner.getBoundingClientRect();
    started = precise = false; suppress = null;
    mark = e.target.closest<HTMLElement>('.mark,.scene-stop');
    // Leave a simple tap on its native button. The permanent surface claims a drag in begin().
    if (!mark) { begin(); e.preventDefault(); }
    hold = window.setTimeout(lock, 380);
  });
  window.addEventListener('pointermove', e => {
    if (pointer !== e.pointerId) return;
    const dx = Math.abs(e.clientX - startX), up = startY - e.clientY;
    if (!started && dx < 5 && Math.abs(up) < 5) return;
    begin();
    if (dx > 5 || Math.abs(up) > 5) window.clearTimeout(hold);
    if (!precise && up >= 18) lock();
    x = e.clientX;
    if (!frame) frame = requestAnimationFrame(flush);
  });
  function finish(e: PointerEvent): void {
    if (e.pointerId !== pointer) return;
    pointer = null;
    window.clearTimeout(hold);
    cancelAnimationFrame(frame); frame = 0;
    if (!started) return; // A tap on a checkpoint goes to its existing button handler.
    if (e.type === 'pointerup') { x = e.clientX; flush(); }
    track.classList.remove('is-dragging');
    lens.close();
    options.onScrubChange(false);
    started = false;
    if (precise && e.type === 'pointerup') options.onFineCommit(year);
  }
  for (const type of ['pointerup', 'pointercancel'] as const) window.addEventListener(type, finish);
  surface.addEventListener('lostpointercapture', e => {
    if (started && e.target === surface) finish(e);
  });
  surface.addEventListener('click', e => {
    if (e.detail !== 0 && suppress && e.target instanceof Node && suppress.contains(e.target)) {
      e.stopImmediatePropagation(); e.preventDefault(); suppress = null;
    }
  }, true);
}
