// First-visit coach marks: three short hints, one at a time, pointing at the era band, the
// timeline handle and the map. They wait until the opening sweep and the short tour are out
// of the way, run once per browser (localStorage), and never steal focus. Skip, Escape or
// finishing the third hint ends them for good.

import { el } from './dom.ts';
import { ESCAPE_PRIORITY, registerEscape } from './escape.ts';
import { introRunning } from './intro.ts';
import { revealErasForHint } from './timeline/chronicleDock.ts';
import { getState, subscribe } from './state.ts';

const KEY = 'coach-seen';

interface Step {
  /** CSS selector of the element the hint points at; null points at the middle of the map. */
  target: string | null;
  text: string;
}

const STEPS: readonly Step[] = [
  { target: '.eras', text: 'Tap an era to jump straight to it. Tap the active era again to zoom the timeline into it.' },
  { target: '.track', text: 'Drag the handle to travel through time. The arrow keys work too.' },
  { target: null, text: 'Tap a place name to open its card, with sources for every claim.' },
];

function seen(): boolean {
  try {
    return window.localStorage.getItem(KEY) === '1';
  } catch {
    return false;
  }
}

function remember(): void {
  try {
    window.localStorage.setItem(KEY, '1');
  } catch {
    // Storage can be blocked; the hints then show again next visit.
  }
}

export function initCoachMarks(): void {
  if (seen() || document.documentElement.dataset['embed'] !== undefined) return;

  let index = 0;
  let box: HTMLElement | null = null;
  let timer = 0;
  let started = false;
  let endEraHint: (() => void) | undefined;

  const place = (): void => {
    if (!box) return;
    const step = STEPS[index];
    if (!step) return;
    const area = document.getElementById('map')?.getBoundingClientRect();
    const target = step.target === null ? null : document.querySelector(step.target)?.getBoundingClientRect();
    const margin = 12;
    const width = Math.min(box.offsetWidth || 300, window.innerWidth - 2 * margin);
    // Centre over the target (or the map), then keep inside the viewport.
    const centre = target ? target.left + target.width / 2 : (area ? area.left + area.width / 2 : window.innerWidth / 2);
    const left = Math.min(window.innerWidth - width - margin, Math.max(margin, centre - width / 2));
    box.style.left = `${left}px`;
    box.style.setProperty('--pointer-x', `${Math.min(width - 22, Math.max(22, centre - left))}px`);
    if (target) {
      box.dataset['side'] = 'above';
      box.style.top = 'auto';
      box.style.bottom = `${Math.max(margin, window.innerHeight - target.top + 10)}px`;
    } else {
      box.dataset['side'] = 'none';
      box.style.bottom = 'auto';
      box.style.top = `${Math.max(margin, (area?.top ?? 0) + (area?.height ?? window.innerHeight) * 0.4)}px`;
    }
  };

  const end = (): void => {
    endEraHint?.();
    remember();
    window.clearTimeout(timer);
    window.removeEventListener('resize', place);
    box?.remove();
    box = null;
  };

  const render = (): void => {
    const step = STEPS[index];
    if (!box || !step) return;
    endEraHint?.();
    endEraHint = step.target === '.eras' ? revealErasForHint() : undefined;
    const last = index === STEPS.length - 1;
    const skip = el('button', 'btn coach__skip', 'Skip');
    skip.type = 'button';
    skip.addEventListener('click', end);
    const next = el('button', 'btn coach__next', last ? 'Got it' : 'Next');
    next.type = 'button';
    next.addEventListener('click', () => {
      if (last) {
        end();
        return;
      }
      index += 1;
      render();
    });
    box.replaceChildren(
      el('p', 'coach__text', step.text),
      el('div', 'coach__row', undefined),
    );
    const row = box.querySelector('.coach__row');
    row?.append(el('span', 'coach__count', `${index + 1} of ${STEPS.length}`), skip, next);
    place();
  };

  const begin = (): void => {
    if (started || seen()) return;
    started = true;
    remember(); // shown once: a reload part-way through does not bring them back
    box = el('aside', 'coach');
    box.setAttribute('role', 'status');
    box.setAttribute('aria-live', 'polite');
    document.body.append(box);
    registerEscape({ priority: ESCAPE_PRIORITY.coach, isOpen: () => box !== null, close: end });
    window.addEventListener('resize', place);
    render();
  };

  // Start a moment after the tour is closed, or on a plain visit once nothing else is running.
  const arm = (): void => {
    window.clearTimeout(timer);
    timer = window.setTimeout(() => {
      if (getState().story === null && !introRunning()) begin();
      else arm();
    }, 1800);
  };
  arm();
  subscribe((state, previous) => {
    if (started) return;
    if (state.story === null && previous.story !== null) arm();
  });
}
