import { toAstronomical, toHistorical } from '../data/spans.ts';
import type { Scale } from './scale.ts';

const clamp = (x: number, a: number, b: number) => Math.max(a, Math.min(b, x));
type Limits = Pick<Scale, 'minYear' | 'maxYear'>;

/** Fine ticks represent individual calendar years, including the adjacent years 1 BCE and 1 CE. */
export function lensRange(year: number, fraction: number, scale: Limits, checkpoints: ReadonlySet<number>) {
  const min = toAstronomical(scale.minYear), max = toAstronomical(scale.maxYear);
  const center = clamp(toAstronomical(year), min, max);
  let nearby = 0;
  for (let at = center - 5; at <= center + 5 && nearby < 2; at++) {
    if (checkpoints.has(toHistorical(at))) nearby++;
  }
  const span = Math.min(nearby >= 2 ? 10 : 22, max - min);
  const first = clamp(center - Math.round(span * clamp(fraction, 0, 1)), min, max - span);
  return { first, last: first + span, span };
}

export function fineYear(anchor: number, delta: number, pixelsPerYear: number, scale: Limits): number {
  const year = toAstronomical(anchor) + Math.round(delta / Math.max(1, pixelsPerYear));
  return toHistorical(clamp(year, toAstronomical(scale.minYear), toAstronomical(scale.maxYear)));
}
