import { luminance } from './color.ts';
import type { Palette } from './style.ts';

/** The end folds and little city gate stay fixed as the paper expands around both names. */
export function drawDistrictRibbon(g: CanvasRenderingContext2D, palette: Palette, focused: boolean): void {
  const night = luminance(palette.paper) < .5;
  const ink = night ? '#302b22' : '#372f22';
  const shape = (points: readonly (readonly [number, number])[], fill: string): void => {
    g.beginPath();
    points.forEach(([x, y], i) => i ? g.lineTo(x, y) : g.moveTo(x, y));
    g.closePath(); g.fillStyle = fill; g.fill(); g.stroke();
  };
  g.lineJoin = 'round'; g.strokeStyle = ink; g.lineWidth = 1;
  for (const flip of [false, true]) {
    g.save();
    if (flip) { g.translate(92, 0); g.scale(-1, 1); }
    shape([[1,9],[13,9],[13,38],[1,38],[4,24]], night ? '#a3997f' : '#d8c9a8');
    shape([[9,32],[14,38],[9,38]], '#918468');
    g.restore();
  }
  const paper = g.createLinearGradient(0, 2, 0, 35);
  paper.addColorStop(0, night ? '#d9cfb6' : '#f9efd8');
  paper.addColorStop(.6, night ? '#c9bea4' : '#eee1c2');
  paper.addColorStop(1, night ? '#b5a88d' : '#dfcfad');
  g.fillStyle = paper; g.fillRect(9, 2, 74, 32);
  g.lineWidth = focused ? 1.8 : 1.25;
  g.strokeRect(9, 2, 74, 32);
  if (focused) {
    g.strokeStyle = '#8c754a'; g.lineWidth = .65; g.strokeRect(11, 4, 70, 28);
  }
  // A woodcut gate, cut through to the same paper as the inscription.
  g.fillStyle = ink;
  for (const x of [13, 24]) {
    g.fillRect(x, 15, 5, 10);
    g.fillRect(x, 12.5, 1.7, 3); g.fillRect(x + 3.3, 12.5, 1.7, 3);
  }
  g.fillRect(17, 17, 8, 8);
  g.fillStyle = paper;
  g.beginPath(); g.arc(21, 21.5, 2.1, Math.PI, 0);
  g.lineTo(23.1, 25); g.lineTo(18.9, 25); g.fill();
}
