// The first-visit opening ends on the interactive map and yields immediately to input.

import { el } from './dom.ts';
import { introFlight, stopCamera } from './map/camera.ts';
import { cancelYearAnimation, goToYear, timelineRange } from './timeline/navigate.ts';

const KEY = 'atlas-intro-seen';
const SWEEP_MS = 3400;

export function introRunning(): boolean {
  return document.documentElement.hasAttribute('data-atlas-intro');
}

function firstVisit(): boolean {
  try {
    if (window.localStorage.getItem(KEY) === '1') return false;
    window.localStorage.setItem(KEY, '1');
  } catch {
    // The opening is still dismissible when storage is unavailable.
  }
  return true;
}

export function runIntro(): void {
  const range = timelineRange();
  const host = document.getElementById('map');
  const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const root = document.documentElement;
  if (!range || !host || motion.matches || window.location.hash || root.hasAttribute('data-embed') || !firstVisit()) return;

  const cover = el('div', 'atlas-opening');
  cover.setAttribute('aria-hidden', 'true');
  cover.append(el('p', 'atlas-opening__title', document.title));
  host.append(cover);
  root.setAttribute('data-atlas-intro', '');

  function finish(): void {
    if (!introRunning()) return;
    root.removeAttribute('data-atlas-intro');
    window.removeEventListener('pointerdown', cancel, true);
    window.removeEventListener('keydown', cancel, true);
    motion.removeEventListener('change', cancel);
    cover.remove();
  }

  function cancel(): void {
    cancelYearAnimation();
    stopCamera();
    if (range) goToYear(range.max, undefined, 0);
    finish();
  }

  window.addEventListener('pointerdown', cancel, true);
  window.addEventListener('keydown', cancel, true);
  motion.addEventListener('change', cancel);

  goToYear(range.min, undefined, 0);
  introFlight(SWEEP_MS);
  window.requestAnimationFrame(() => {
    if (introRunning()) goToYear(range.max, finish, SWEEP_MS);
  });
}
