// A small toast shown the first time the reader lands in each era: the era's name, years
// and a two-line orientation drawn from this map's own events. Once per era per visit;
// never during playback; dismissible; polite for screen readers.

import { eraById } from '../data/eras.ts';
import type { EraId } from '../data/eras.ts';
import { formatYear } from '../data/format.ts';
import { el } from '../dom.ts';
import { getState, subscribe } from '../state.ts';
import { introRunning } from '../intro.ts';

const SHOW_MS = 9000;
const SETTLE_MS = 700;

export function initEraSummaries(host: HTMLElement): void {
  const toast = el('aside', 'era-toast');
  toast.hidden = true;
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');

  const title = el('p', 'era-toast__title');
  const text = el('p', 'era-toast__text');
  const close = el('button', 'era-toast__close', '×');
  close.type = 'button';
  close.setAttribute('aria-label', 'Dismiss era summary');
  close.addEventListener('click', () => {
    toast.hidden = true;
  });
  toast.append(close, title, text);
  host.append(toast);

  const shown = new Set<EraId>();
  let hideTimer = 0;
  let settleTimer = 0;

  function show(id: EraId): void {
    if (shown.has(id)) return;
    const era = eraById(id);
    if (!era.summary) return;
    shown.add(id);
    const end = era.end === null ? 'today' : formatYear(era.end, true);
    title.textContent = `${era.label} · ${formatYear(era.start, true)} – ${end}`;
    text.textContent = era.summary;
    toast.hidden = false;
    window.clearTimeout(hideTimer);
    hideTimer = window.setTimeout(() => {
      toast.hidden = true;
    }, SHOW_MS);
  }

  subscribe((state, previous) => {
    if (state.activeEra === previous.activeEra && state.isScrubbing === previous.isScrubbing &&
        state.isPlaying === previous.isPlaying) return;
    window.clearTimeout(settleTimer);
    toast.hidden = true;
    if (state.isScrubbing || state.isPlaying || introRunning()) return;
    settleTimer = window.setTimeout(() => {
      const current = getState();
      if (current.activeEra !== null && current.story === null && !current.isScrubbing && !current.isPlaying &&
          current.selectedEventId === null && current.selectedPlaceId === null && !introRunning()) show(current.activeEra);
    }, SETTLE_MS);
  });
}
