// The director: plays a story as a film. It walks the beats from plan.ts on a pausable clock,
// asks the story system to fly the camera and glide the year for each step, shows the cards and
// captions, cues the sound, and handles pause, skip and exit. The map itself is untouched: the
// film is a layer over the same story the reader can step through by hand.

import { formatYear } from '../data/format.ts';
import { HOME_BOUNDS } from '../data/region.ts';
import { ESCAPE_PRIORITY, registerEscape } from '../escape.ts';
import { driftCamera, fitToBounds, stopCamera } from '../map/camera.ts';
import { setState } from '../state.ts';
import { describeStory, startStory } from '../story/controls.ts';
import { copyText } from '../feedback.ts';
import { ARRIVE_MS, beatMs, buildBeats } from './plan.ts';
import type { Beat } from './plan.ts';
import { createFilmUi } from './overlay.ts';
import { createFilmSound } from './sound.ts';

const TICK_MS = 100;

export interface Director {
  play(storyId: string): void;
  stop(): void;
  running(): boolean;
}

export function createDirector(hooks: { onStop(): void }): Director {
  const sound = createFilmSound();
  let beats: Beat[] = [];
  let storyId = '';
  let index = 0;
  let elapsed = 0;
  let revealed = false;
  let paused = false;
  let isRunning = false;
  let timer = 0;
  let last = 0;

  const ui = createFilmUi({
    prev: () => go(Math.max(0, index - 1)),
    next: () => go(Math.min(beats.length - 1, index + 1)),
    toggle: () => pause(!paused),
    sound: () => toggleSound(),
    exit: () => stop(),
    jump: (beat) => go(beat),
    browse: () => pause(true),
  });
  document.body.append(ui.element);

  function stepsTotal(): number {
    return beats.filter((b) => b.kind === 'step').length;
  }

  /** Starts the slow push-in for what is left of the current step. */
  function drift(): void {
    const beat = beats[index];
    const length = beat ? beatMs(beat) : null;
    if (beat?.kind === 'step' && length !== null) driftCamera(Math.max(1000, length - elapsed));
  }

  function pause(next: boolean): void {
    if (next === paused || beats[index]?.kind === 'close') return;
    paused = next;
    ui.setPaused(next);
    // The shot holds still while paused and carries on from there.
    if (next) {
      if (revealed) stopCamera();
    } else if (isRunning && revealed) drift();
  }

  function toggleSound(): void {
    sound.setEnabled(!sound.enabled());
    ui.setSound(sound.enabled());
    sound.drone(isRunning && beats[index]?.kind !== 'close');
  }

  function closeCard(title: string): Parameters<typeof ui.card>[0] {
    const link = `${window.location.origin}${window.location.pathname}#film=${storyId}`;
    return {
      kicker: 'The end',
      title,
      text: 'That was the short version. Every place and event on the map has its own card, with the sources behind it.',
      actions: [
        { label: 'Explore the map', primary: true, run: () => stop() },
        { label: 'Watch again', run: () => go(0) },
        { label: 'Copy link to this film', run: () => void copyText(link) },
      ],
    };
  }

  /** Moves to a beat and starts it. */
  function go(i: number): void {
    index = Math.min(beats.length - 1, Math.max(0, i));
    elapsed = 0;
    revealed = false;
    const beat = beats[index];
    if (!beat) return;
    // A new beat always plays, even if the last one was paused.
    paused = false;
    ui.setPaused(false);
    ui.showBeat(index, beats.length, beat.kind === 'close');
    sound.drone(beat.kind !== 'close');
    switch (beat.kind) {
      case 'open':
        ui.caption(null);
        startStory(storyId, 0);
        ui.progress(0, stepsTotal());
        ui.card({
          kicker: `A film in ${beat.parts} parts`,
          title: beat.title,
          sub: `About ${beat.minutes} ${beat.minutes === 1 ? 'minute' : 'minutes'}`,
          text: beat.intro,
        });
        sound.cue('seal');
        break;
      case 'era': {
        ui.caption(null);
        const end = beat.era.end === null ? 'today' : formatYear(beat.era.end, true);
        ui.card({
          kicker: 'The era',
          title: beat.era.label,
          sub: `${formatYear(beat.era.start, true)} – ${end}`,
          ...(beat.era.summary ? { text: beat.era.summary } : {}),
        });
        sound.cue('seal');
        break;
      }
      case 'step':
        ui.card(null);
        ui.caption(null);
        ui.progress(beat.step - 1, beat.total);
        startStory(storyId, beat.step);
        break;
      case 'close':
        ui.caption(null);
        ui.progress(stepsTotal(), stepsTotal());
        ui.card(closeCard(beat.title));
        sound.cue('seal');
        break;
    }
  }

  function tick(): void {
    const now = performance.now();
    const dt = now - last;
    last = now;
    if (paused || !isRunning) return;
    elapsed += dt;
    const beat = beats[index];
    if (!beat) return;
    if (beat.kind === 'step' && !revealed && elapsed >= ARRIVE_MS) {
      revealed = true;
      ui.caption({ chapter: `Part ${beat.step} of ${beat.total}`, heading: beat.title, text: beat.caption });
      sound.cue('paper');
      drift();
    }
    const length = beatMs(beat);
    if (length !== null && elapsed >= length) go(index + 1);
  }

  function onKey(e: KeyboardEvent): void {
    if (!isRunning || e.altKey || e.ctrlKey || e.metaKey) return;
    if (ui.chaptersOpen()) return;
    const target = e.target;
    const onControl = target instanceof HTMLElement && ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(target.tagName);
    if (e.key === ' ' && !onControl) {
      e.preventDefault();
      pause(!paused);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      go(index + 1);
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      go(index - 1);
    } else if (e.key === 'm' || e.key === 'M') {
      toggleSound();
    }
  }

  // A film left running in a hidden tab would play on without anyone watching.
  const onHidden = (): void => {
    if (isRunning && document.hidden) pause(true);
  };

  function stop(): void {
    if (!isRunning) return;
    isRunning = false;
    window.clearInterval(timer);
    document.removeEventListener('keydown', onKey, true);
    document.removeEventListener('visibilitychange', onHidden);
    sound.drone(false);
    ui.close();
    setState({ story: null, dimOthers: false, selectedEventId: null });
    fitToBounds(HOME_BOUNDS);
    hooks.onStop();
  }

  registerEscape({
    priority: ESCAPE_PRIORITY.film,
    isOpen: () => isRunning,
    close: () => {
      if (ui.chaptersOpen()) ui.closeChapters();
      else stop();
    },
  });

  return {
    running: () => isRunning,
    stop,
    play(id) {
      const story = describeStory(id);
      if (!story || story.steps.length === 0) return;
      if (isRunning) stop();
      storyId = id;
      beats = buildBeats(story);
      isRunning = true;
      ui.open(beats.flatMap((beat, i) => beat.kind === 'step' ? [{ index: i, title: beat.title, number: beat.step }] : []));
      ui.setSound(sound.enabled());
      document.addEventListener('keydown', onKey, true);
      document.addEventListener('visibilitychange', onHidden);
      last = performance.now();
      timer = window.setInterval(tick, TICK_MS);
      go(0);
    },
  };
}
