import type { ImageSourceSpecification, RasterLayerSpecification } from 'maplibre-gl';
import { luminance } from './color.ts';
import { activeStrength } from './look.ts';
import type { Palette } from './style.ts';

export const RELIEF_PLATE = 'look-relief-plate';
export const TERRAIN_INK = 'look-terrain-impression';

// The bake uses these exact Web Mercator tile edges at zoom eight.
function corner(x: number, y: number): [number, number] {
  const latitude = Math.atan(Math.sinh(Math.PI * (1 - 2 * y / 256)));
  return [360 * x / 256 - 180, latitude * 180 / Math.PI];
}

export function reliefSource(file: 'relief' | 'terrain-impression' = 'relief'): ImageSourceSpecification {
  return {
    type: 'image',
    url: new URL('art/' + file + '.webp', document.baseURI).href,
    coordinates: [corner(151, 102), corner(155, 102), corner(155, 107), corner(151, 107)],
  };
}

export function reliefPaint(p: Palette): NonNullable<RasterLayerSpecification['paint']> {
  const night = luminance(p.paper) < 0.5;
  return {
    'raster-opacity': ['interpolate', ['linear'], ['zoom'], 5, 0.86, 8, 0.78, 10, 0.2, 11, 0],
    'raster-brightness-max': night ? 0.38 : 1,
    'raster-saturation': night ? -0.6 : -0.12,
    'raster-fade-duration': 0,
  };
}

export function impressionPaint(p: Palette): NonNullable<RasterLayerSpecification['paint']> {
  const strength = activeStrength() === 'subtle' ? .47 : 1;
  const night = luminance(p.paper) < .5;
  return {
    'raster-opacity': ['interpolate', ['linear'], ['zoom'], 5, .61 * strength, 7, .96 * strength,
      8.6, .73 * strength, 9.6, .22 * strength, 10.4, 0],
    'raster-brightness-min': night ? .58 : 0,
    'raster-fade-duration': 0,
  };
}

export function impressionLayer(p: Palette): RasterLayerSpecification {
  return { id: TERRAIN_INK, source: TERRAIN_INK, type: 'raster', maxzoom: 10.4, paint: impressionPaint(p) };
}

export function reliefLayer(p: Palette): RasterLayerSpecification {
  return { id: RELIEF_PLATE, source: RELIEF_PLATE, type: 'raster', maxzoom: 11, paint: reliefPaint(p) };
}
