import { CATEGORIES } from '../data/categories.ts';
import { formatEventDate } from '../data/format.ts';
import type { ResolvedPath } from '../data/pathTypes.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { el } from '../dom.ts';
import { icon } from '../icons.ts';
import type { IconName } from '../icons.ts';
import { categoryIcon } from '../categoryIcon.ts';
import { scenePlate } from './scenePlate.ts';
import { routeLine } from '../panel/render.ts';
import { isLandEvent } from '../map/sceneExtent.ts';

export function sceneControl(label: string, name: IconName, act: () => void): HTMLButtonElement {
  const button = el('button', 'scene-control');
  button.type = 'button';
  button.setAttribute('aria-label', label);
  button.title = label;
  button.append(icon(name, 17));
  button.addEventListener('click', act);
  return button;
}

export function createSceneCard(actions: { details(): void; close(): void; step(by: number): void }) {
  const element = el('section', 'rail-popover scene-card');
  element.hidden = true;
  element.setAttribute('aria-labelledby', 'scene-title');
  const art = el('div', 'scene-card__print');
  const date = el('span', 'scene-card__date');
  const place = el('span', 'scene-card__place');
  const caption = el('div', 'scene-card__legend');
  caption.append(date, place);
  const close = sceneControl('Close', 'close', actions.close);
  close.classList.add('scene-close');
  const heading = el('h2', 'scene-card__title');
  heading.id = 'scene-title'; heading.tabIndex = -1; heading.dir = 'auto';
  const body = el('div', 'scene-card__body');
  const back = sceneControl('Previous', 'prev', () => actions.step(-1));
  const next = sceneControl('Next', 'next', () => actions.step(1));
  const open = el('button', 'scene-card__open');
  open.type = 'button'; open.append(icon('sources', 16), el('span', '', 'Open full card'));
  open.addEventListener('click', actions.details);
  const foot = el('div', 'scene-card__foot');
  foot.append(open, back, next);
  body.append(heading, foot);
  const header = el('div', 'scene-card__header');
  header.append(art, caption);
  element.append(header, close, body);
  return { element, heading, back, next,
    show(event: HistoricalEvent, paths: readonly ResolvedPath[]): void {
      const category = CATEGORIES.find(c => c.id === event.category);
      art.replaceChildren(scenePlate(event, paths));
      if (isLandEvent(event.location)) {
        const seal = el('img', 'scene-land-medal');
        seal.alt = ''; seal.src = new URL('art/scene-land.webp', document.baseURI).href;
        art.append(seal);
      }
      if (paths.length) {
        const shape = el('span', 'scene-card__shape', paths[0]!.shape);
        shape.title = paths.map(p => routeLine(p).textContent).join(' · ');
        art.append(shape);
      }
      date.replaceChildren(...(category ? [categoryIcon(category)] : []), el('span', '', formatEventDate(event)));
      place.dir = 'auto';
      place.textContent = event.location.nameAr ? event.location.name + ' · ' + event.location.nameAr : event.location.name;
      heading.textContent = event.title;
      element.dataset.event = event.id;
      element.hidden = false;
    },
  };
}
