// "Share as image": draws a card picture (1200 x 630) with the name, the Arabic name and a few key facts, and shares or downloads it
// so it can be posted in a chat. Drawn in the browser with canvas, nothing is uploaded.

import { formatEventDate, formatYear } from './data/format.ts';
import type { Place } from './data/placeTypes.ts';
import type { HistoricalEvent } from './data/types.ts';
import { el } from './dom.ts';
import { copyText, currentLink } from './feedback.ts';

export interface ShareCardData {
  kind: string;
  title: string;
  arabic: string | null;
  lines: string[];
  footer: string;
}

const W = 1200;
const H = 630;

function wrap(g: CanvasRenderingContext2D, text: string, width: number, maxLines: number): string[] {
  const words = text.split(/\s+/);
  const lines: string[] = [];
  let line = '';
  for (const word of words) {
    const next = line === '' ? word : `${line} ${word}`;
    if (g.measureText(next).width > width && line !== '') {
      lines.push(line);
      line = word;
    } else line = next;
    if (lines.length === maxLines) break;
  }
  if (lines.length < maxLines && line !== '') lines.push(line);
  if (lines.length === maxLines && words.join(' ').length > lines.join(' ').length) lines[maxLines - 1] = `${(lines[maxLines - 1] ?? '').replace(/[ ,.;:]+$/, '')}...`;
  return lines;
}

/** The display face the page already loads, with safe fallbacks for when it has not arrived. */
const DISPLAY = '"Cormorant Garamond", Georgia, "Times New Roman", serif';
const UI = '"IBM Plex Sans", Arial, sans-serif';

/** Canvas letter-spacing exists in current browsers; where it does not the text is simply set tight. */
function tracked(g: CanvasRenderingContext2D, spacing: string): void {
  if ('letterSpacing' in g) (g as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = spacing;
}

/** A faint eight-point compass, drawn once as a watermark. */
function compass(g: CanvasRenderingContext2D, cx: number, cy: number, r: number): void {
  g.save();
  g.translate(cx, cy);
  g.strokeStyle = '#4a3a28';
  g.fillStyle = '#4a3a28';
  g.lineWidth = 2;
  g.beginPath();
  g.arc(0, 0, r * 0.66, 0, Math.PI * 2);
  g.stroke();
  g.beginPath();
  g.arc(0, 0, r * 0.54, 0, Math.PI * 2);
  g.lineWidth = 1;
  g.stroke();
  for (let i = 0; i < 4; i++) {
    g.save();
    g.rotate((i * Math.PI) / 2);
    g.beginPath();
    g.moveTo(0, -r);
    g.lineTo(r * 0.13, -r * 0.13);
    g.lineTo(0, 0);
    g.closePath();
    g.globalAlpha = 0.55;
    g.fill();
    g.globalAlpha = 1;
    g.beginPath();
    g.moveTo(0, -r);
    g.lineTo(r * 0.13, -r * 0.13);
    g.lineTo(-r * 0.13, -r * 0.13);
    g.closePath();
    g.stroke();
    g.restore();
  }
  g.restore();
}

export async function drawShareCard(data: ShareCardData): Promise<Blob | null> {
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const g = canvas.getContext('2d');
  if (!g) return null;

  // Parchment, lighter in the middle, with a soft edge darkening.
  const paper = g.createRadialGradient(W * 0.45, H * 0.4, 80, W * 0.5, H * 0.5, W * 0.75);
  paper.addColorStop(0, '#f6eeda');
  paper.addColorStop(0.6, '#eadfc0');
  paper.addColorStop(1, '#dccaa0');
  g.fillStyle = paper;
  g.fillRect(0, 0, W, H);

  // A faint compass behind the right-hand side.
  g.save();
  g.globalAlpha = 0.1;
  compass(g, 975, 262, 160);
  g.restore();

  // Double-ruled frame, like the chart's edge.
  g.strokeStyle = 'rgba(74, 58, 40, 0.5)';
  g.lineWidth = 2;
  g.strokeRect(22, 22, W - 44, H - 44);
  g.strokeStyle = 'rgba(74, 58, 40, 0.22)';
  g.lineWidth = 1;
  g.strokeRect(32, 32, W - 64, H - 64);

  g.textBaseline = 'alphabetic';
  g.textAlign = 'left';

  // Kind: small capitals, tracked, in the accent colour.
  g.fillStyle = '#8c3b2e';
  g.font = `600 24px ${UI}`;
  tracked(g, '6px');
  g.fillText(data.kind.toUpperCase(), 80, 98);
  tracked(g, '0px');

  // Title in the display face, with a double rule beneath it.
  g.fillStyle = '#2b2117';
  g.font = `700 74px ${DISPLAY}`;
  const titleLines = wrap(g, data.title, 720, 2);
  titleLines.forEach((line, i) => g.fillText(line, 80, 172 + i * 78));
  let y = 172 + (titleLines.length - 1) * 78;
  if (data.arabic) {
    g.font = `600 52px "IBM Plex Sans Arabic", "Segoe UI", Arial, sans-serif`;
    g.direction = 'rtl';
    g.fillStyle = '#4a3b27';
    g.fillText(data.arabic, 80, y + 68);
    g.direction = 'ltr';
    y += 68;
  }
  y += 34;
  g.fillStyle = 'rgba(74, 58, 40, 0.55)';
  g.fillRect(80, y, 560, 2);
  g.fillStyle = 'rgba(74, 58, 40, 0.25)';
  g.fillRect(80, y + 6, 560, 1);

  g.fillStyle = '#3b2f20';
  g.font = `29px ${UI}`;
  y += 56;
  for (const text of data.lines.slice(0, 5)) {
    const lines = wrap(g, text, 740, 2);
    for (const line of lines) {
      g.fillText(line, 80, y);
      y += 40;
    }
  }

  g.fillStyle = '#6b5a40';
  g.font = `22px ${UI}`;
  g.fillText(data.footer, 80, H - 62);

  // The site name in a small ruled cartouche, bottom right.
  g.font = `700 30px ${DISPLAY}`;
  tracked(g, '4px');
  const name = '1PALESTINE';
  const nameW = g.measureText(name).width;
  g.font = `italic 500 30px ${DISPLAY}`;
  tracked(g, '1px');
  const mapW = g.measureText(' Map').width;
  const boxW = nameW + mapW + 44;
  const boxX = W - 70 - boxW;
  const boxY = H - 108;
  g.fillStyle = 'rgba(247, 239, 222, 0.85)';
  g.fillRect(boxX, boxY, boxW, 54);
  g.strokeStyle = '#a98f66';
  g.lineWidth = 2;
  g.strokeRect(boxX, boxY, boxW, 54);
  g.strokeStyle = 'rgba(169, 143, 102, 0.55)';
  g.lineWidth = 1;
  g.strokeRect(boxX + 5, boxY + 5, boxW - 10, 44);
  g.fillStyle = '#2b2117';
  g.font = `700 30px ${DISPLAY}`;
  tracked(g, '4px');
  g.fillText(name, boxX + 22, boxY + 37);
  g.font = `italic 500 30px ${DISPLAY}`;
  tracked(g, '1px');
  g.fillText(' Map', boxX + 22 + nameW, boxY + 37);
  tracked(g, '0px');

  return new Promise((resolve) => canvas.toBlob((blob) => resolve(blob), 'image/png'));
}

const fileName = (title: string): string => `${title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'card'}.png`;

/** Shares the picture (a phone's share sheet) or downloads it and copies the link; returns what happened in words. */
export async function shareCardImage(data: ShareCardData): Promise<string> {
  const blob = await drawShareCard(data);
  if (!blob) return 'Could not make the picture.';
  const file = new File([blob], fileName(data.title), { type: 'image/png' });
  const link = currentLink();
  if (typeof navigator.canShare === 'function' && navigator.canShare({ files: [file] })) {
    try {
      await navigator.share({ files: [file], title: data.title, text: link });
      return 'Shared.';
    } catch {
      return 'Sharing was cancelled.';
    }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = file.name;
  document.body.append(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 4000);
  const copied = await copyText(link);
  return copied ? 'Picture saved, and the link is copied.' : 'Picture saved.';
}

export function placeCardData(place: Place, year: number): ShareCardData {
  const now = place.names.find((n) => n.from !== null && (n.to === null || n.to >= year) && n.from <= year) ?? place.names[0];
  const f = place.facts;
  const lines: string[] = [];
  if (f?.subDistrict) lines.push(`Mandate sub-district: ${f.subDistrict}`);
  if (f?.occupied) lines.push(`Occupied: ${f.occupied.text}`);
  if (f?.population) lines.push(`Population in ${f.population.year}: ${f.population.value.toLocaleString('en-US')}`);
  else if (f?.population1944) lines.push(`Population in ${f.population1944.year}: ${f.population1944.value.toLocaleString('en-US')}`);
  if (place.depopulated !== undefined) lines.push(`Depopulated in ${formatYear(place.depopulated, true)}`);
  if (f?.localities?.length) lines.push(`Israeli locality on its land: ${f.localities.map((l) => l.name).join(', ')}`);
  return {
    kind: place.kind === 'village' ? 'Village' : place.kind,
    title: now?.en ?? place.id,
    arabic: now?.ar ?? null,
    lines,
    footer: 'Sources: see the card. Needs review.',
  };
}

export function eventCardData(event: HistoricalEvent): ShareCardData {
  return {
    kind: event.category.replace(/-/g, ' '),
    title: event.title,
    arabic: event.location.nameAr ?? null,
    lines: [formatEventDate(event), event.location.name, event.summary],
    footer: 'Sources: see the card. Needs review.',
  };
}

/** The button shown on cards. */
export function shareImageButton(make: () => ShareCardData): HTMLElement {
  const wrap = el('span', 'card__share-image');
  const button = el('button', 'btn', 'Share as image');
  button.type = 'button';
  const status = el('span', 'sr-only');
  status.setAttribute('role', 'status');
  button.addEventListener('click', () => {
    button.disabled = true;
    void shareCardImage(make()).then((message) => {
      status.textContent = message;
      button.textContent = message.startsWith('Picture saved') ? 'Picture saved' : 'Share as image';
      button.disabled = false;
    });
  });
  wrap.append(button, status);
  return wrap;
}
