import { el } from '../dom.ts';

export interface FilmChapter {
  index: number;
  title: string;
  number: number;
}

export function createChapters(jump: (index: number) => void, browse: () => void) {
  const toggle = el('button', 'film__chapters-toggle', 'Chapters');
  toggle.type = 'button';
  toggle.setAttribute('aria-expanded', 'false');
  toggle.setAttribute('aria-controls', 'film-chapters');

  const panel = el('nav', 'film__chapters');
  panel.id = 'film-chapters';
  panel.setAttribute('aria-label', 'Chapters');
  panel.hidden = true;

  const title = el('h2', 'film__chapters-title', 'Chapters');
  const list = el('ol', 'film__chapters-list');
  panel.append(title, list);

  function close(restoreFocus = true): void {
    panel.hidden = true;
    toggle.setAttribute('aria-expanded', 'false');
    if (restoreFocus) toggle.focus({ preventScroll: true });
  }

  toggle.addEventListener('click', () => {
    if (!panel.hidden) {
      close();
      return;
    }
    browse();
    panel.hidden = false;
    toggle.setAttribute('aria-expanded', 'true');
    (panel.querySelector<HTMLButtonElement>('[aria-current="step"]') ??
      panel.querySelector('button'))?.focus();
  });

  return {
    toggle,
    panel,
    close,
    isOpen: () => !panel.hidden,
    load(chapters: FilmChapter[]) {
      list.replaceChildren(...chapters.map((chapter) => {
        const item = el('li');
        const button = el('button', 'film__chapter-link');
        button.type = 'button';
        button.dataset['beat'] = String(chapter.index);
        const number = el('span', 'film__chapter-number', String(chapter.number).padStart(2, '0'));
        number.setAttribute('aria-hidden', 'true');
        const label = el('span', '', chapter.title);
        label.dir = 'auto';
        label.setAttribute('data-no-translate', '');
        button.append(number, label);
        button.addEventListener('click', () => {
          close();
          jump(chapter.index);
        });
        item.append(button);
        return item;
      }));
    },
    mark(index: number) {
      for (const button of list.querySelectorAll('button')) {
        if (Number(button.dataset['beat']) === index) button.setAttribute('aria-current', 'step');
        else button.removeAttribute('aria-current');
      }
    },
  };
}
