// The cinematic film mode: a story played as a directed film (docs/FILM.md). This file only wires
// the entry points: the Watch button, the tour's "Watch as a film" link and a #film=<story> link.
// Modules: plan.ts (beats and timing), director.ts (the clock), overlay.ts (the screen), sound.ts.

import { firstStoryId } from '../story/controls.ts';
import { createDirector } from './director.ts';

export function initFilm(button: HTMLElement): void {
  const id = firstStoryId();
  if (id === null) return; // no stories: no film
  button.hidden = false;

  const director = createDirector({ onStop: () => button.focus({ preventScroll: true }) });
  button.addEventListener('click', () => {
    if (!director.running()) director.play(id);
  });
  // The short tour's introduction offers the same story as a film.
  document.addEventListener('film:start', () => director.play(id));

  // A shared link, #film=<story id>, starts it once the map has settled.
  const linked = /[#&]film=([\w-]+)/.exec(window.location.hash)?.[1];
  if (linked !== undefined) window.setTimeout(() => director.play(linked), 900);
}
