// Fetches public/data/myths.json. Myths are optional: if the file is missing or broken the
// Myths dialog simply does not open, and the button stays hidden.

import type { Myth } from './mythTypes.ts';

export const MYTHS_URL = `${import.meta.env.BASE_URL}data/myths.json`;

const isObj = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = (v: unknown): v is string => typeof v === 'string' && v.trim() !== '';

function toMyth(raw: unknown): Myth | null {
  if (!isObj(raw) || !isText(raw['id']) || !isText(raw['myth']) || !isText(raw['answer'])) return null;
  const eventIds = (Array.isArray(raw['eventIds']) ? raw['eventIds'] : []).filter((id): id is string => isText(id));
  const head = eventIds[0];
  if (head === undefined) return null;
  return {
    id: raw['id'],
    myth: raw['myth'],
    answer: raw['answer'],
    eventIds: [head, ...eventIds.slice(1)],
    status: raw['status'] === 'verified' ? 'verified' : 'needs-review',
  };
}

export async function loadMyths(url: string = MYTHS_URL): Promise<Myth[]> {
  try {
    const response = await fetch(url);
    if (!response.ok) return [];
    const data: unknown = await response.json();
    if (!isObj(data) || data['version'] !== 1 || !Array.isArray(data['myths'])) return [];
    const seen = new Set<string>();
    return (data['myths'] as unknown[]).flatMap((raw) => {
      const myth = toMyth(raw);
      if (!myth || seen.has(myth.id)) return [];
      seen.add(myth.id);
      return [myth];
    });
  } catch (err) {
    console.warn('Myths could not be loaded; the Myths dialog is unavailable.', err);
    return [];
  }
}
