import { el } from '../dom.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { groupDate } from './sceneStops.ts';
import type { StopGroup } from './sceneStops.ts';

declare global {
  interface DocumentEventMap { 'timeline:preview': CustomEvent<readonly HistoricalEvent[]> }
}

function light(events: readonly HistoricalEvent[]): void {
  document.dispatchEvent(new CustomEvent('timeline:preview', { detail: events }));
}

/** A quick look at the first and last entries of a stud, without moving the map or its year. */
export function addStopPreview(track: HTMLElement, dots: HTMLElement, find: (id: string) => StopGroup | undefined,
  available: () => boolean): () => void {
  const preview = el('div', 'stop-preview');
  preview.hidden = true;
  preview.setAttribute('aria-hidden', 'true');
  track.append(preview);
  let timer = 0;

  function clear(): void {
    clearTimeout(timer);
    if (!preview.hidden) light([]);
    preview.hidden = true;
  }
  function show(target: EventTarget | null, delay: number): void {
    const button = target instanceof Element ? target.closest<HTMLButtonElement>('.scene-stop') : null;
    if (!button || !available()) return;
    clear();
    timer = window.setTimeout(() => {
      if (!available() || !button.isConnected) return;
      const group = find(button.dataset.first ?? '');
      const first = group?.events[0], last = group?.events.at(-1);
      if (!group || !first) return;
      const date = el('div', 'stop-preview__date', groupDate(group.events));
      const start = el('span', 'stop-preview__title', first.title);
      start.dir = 'auto';
      preview.replaceChildren(date, start);
      if (last && last !== first) {
        const end = el('span', 'stop-preview__title', last.title);
        end.dir = 'auto'; preview.append(end);
      }
      preview.hidden = false;
      light(last && last !== first ? [first, last] : [first]);
      const x = track.clientWidth * group.position;
      const left = Math.max(-6, Math.min(track.clientWidth - preview.offsetWidth + 6, x - preview.offsetWidth / 2));
      preview.style.left = left + 'px';
      preview.style.setProperty('--stud-x', (x - left) + 'px');
    }, delay);
  }
  dots.addEventListener('pointerover', e => { if (e.pointerType === 'mouse') show(e.target, 130); });
  dots.addEventListener('pointerout', e => {
    if (e.target instanceof Element && e.relatedTarget instanceof Node && e.target.closest('button')?.contains(e.relatedTarget)) return;
    clear();
  });
  dots.addEventListener('focusin', e => { if (e.target instanceof Element && e.target.matches(':focus-visible')) show(e.target, 0); });
  dots.addEventListener('focusout', clear);
  dots.addEventListener('pointerdown', clear);
  return clear;
}
