// Turning a story into a film: a list of beats. The film opens on a title card, shows a card
// whenever the story crosses into a new era, lets each step's caption breathe for as long as it
// takes to read, and closes on an end card. Pure functions, no DOM.

import { ERAS } from '../data/eras.ts';
import type { EraInfo } from '../data/eras.ts';
import { toAstronomical } from '../data/spans.ts';
import type { StoryDescription } from '../story/controls.ts';

export type Beat =
  | { kind: 'open'; title: string; intro: string; parts: number; minutes: number }
  | { kind: 'era'; era: EraInfo }
  | { kind: 'step'; step: number; total: number; title: string; caption: string; year: number }
  | { kind: 'close'; title: string };

/** Time the camera and year take to arrive before the caption appears. */
export const ARRIVE_MS = 1300;
export const OPEN_MS = 4200;
export const ERA_MS = 4300;

const MIN_HOLD_MS = 5200;
const MAX_HOLD_MS = 16000;
/** About 190 words a minute, plus a breath either side. */
const MS_PER_WORD = 320;

/** The era a year falls in. Boundary years go to the later era, as the timeline's own bands do. */
export function eraForYear(year: number): EraInfo {
  const y = toAstronomical(Math.round(year));
  let found = ERAS[0] as EraInfo;
  for (const era of ERAS) if (toAstronomical(era.start) <= y) found = era;
  return found;
}

/** How long a caption stays up after it appears. */
export function holdMs(caption: string): number {
  const words = caption.trim().split(/\s+/).filter(Boolean).length;
  return Math.min(MAX_HOLD_MS, Math.max(MIN_HOLD_MS, 1400 + words * MS_PER_WORD));
}

/** How long a beat runs by itself; null for the end card, which waits for the reader. */
export function beatMs(beat: Beat): number | null {
  switch (beat.kind) {
    case 'open':
      return OPEN_MS;
    case 'era':
      return ERA_MS;
    case 'step':
      return ARRIVE_MS + holdMs(beat.caption);
    case 'close':
      return null;
  }
}

export function buildBeats(story: StoryDescription): Beat[] {
  const steps = story.steps;
  const beats: Beat[] = [];
  let previous: EraInfo | null = null;
  steps.forEach((s, i) => {
    const era = eraForYear(s.year);
    if (previous === null || era.id !== previous.id) beats.push({ kind: 'era', era });
    previous = era;
    beats.push({ kind: 'step', step: i + 1, total: steps.length, title: s.title, caption: s.caption, year: s.year });
  });
  const ms = beats.reduce((sum, b) => sum + (beatMs(b) ?? 0), 0) + OPEN_MS;
  const minutes = Math.max(1, Math.round(ms / 60000));
  return [{ kind: 'open', title: story.title, intro: story.intro, parts: steps.length, minutes }, ...beats, { kind: 'close', title: story.title }];
}
