import { el } from '../dom.ts';
import { ESCAPE_PRIORITY, registerEscape } from '../escape.ts';

interface Parts {
  play: HTMLButtonElement;
  speed: HTMLSelectElement;
  zoom: HTMLButtonElement;
  eras: HTMLElement;
  spark: HTMLElement;
  spine: HTMLElement;
  stops: HTMLElement;
  entries: HTMLElement;
  live: HTMLElement;
}

/** One measured spine for dates, events and scrubbing, with the era index on demand. */
export function mountChronicleDock(container: HTMLElement, parts: Parts): HTMLElement {
  const { play, speed, zoom, eras, spark, spine, stops, entries, live } = parts;
  const eraName = el('span', 'chronicle-era__name');
  const toggle = el('button', 'chronicle-era scene-dial-toggle');
  toggle.type = 'button';
  toggle.append(eraName);
  toggle.title = 'Jump to an era';
  toggle.setAttribute('aria-controls', 'timeline-dial');
  const drawer = el('div', 'chronicle-index');
  drawer.id = 'timeline-dial';
  entries.id = 'timeline-entries';
  const indexRow = el('div', 'chronicle-index__row');
  indexRow.append(eras, speed);
  drawer.append(indexRow, entries);
  const mast = el('div', 'chronicle-transport');
  mast.append(play, toggle);
  spine.prepend(spark);
  spine.append(stops);
  const side = el('div', 'tl-side');
  side.append(zoom);
  container.append(mast, drawer, spine, side, live);

  function expand(open: boolean, returnFocus = false): void {
    drawer.hidden = !open;
    container.toggleAttribute('data-dial-open', open);
    toggle.setAttribute('aria-expanded', String(open));
    if (returnFocus) toggle.focus({ preventScroll: true });
  }
  expand(false);
  toggle.addEventListener('click', () => expand(Boolean(drawer.hidden)));
  drawer.addEventListener('click', e => {
    if (!(e.target instanceof Element)) return;
    if (e.target.closest('.era-entries button')) expand(false);
    else if (e.target.closest('.era-button')) expand(false, true);
  });
  document.addEventListener('pointerdown', e => {
    if (!drawer.hidden && e.target instanceof Node && !container.contains(e.target)) expand(false);
  }, { capture: true, passive: true });
  registerEscape({ priority: ESCAPE_PRIORITY.panel + .5, isOpen: () => !drawer.hidden,
    close: () => expand(false, true) });
  return eraName;
}

/** Existing coach copy points at the era buttons themselves. Show them for that one hint. */
export function revealErasForHint(): () => void {
  const toggle = document.querySelector<HTMLButtonElement>('.chronicle-era');
  if (!toggle || toggle.getAttribute('aria-expanded') === 'true') return () => {};
  toggle.click();
  return () => { if (toggle.getAttribute('aria-expanded') === 'true') toggle.click(); };
}
