// The map's empty state: when no event is active for the chosen year (with the current
// category filters), say so and offer the way out - clear the filters, or jump to the
// nearest year that has events. Hidden while a story runs or an event is open.

import { CATEGORY_IDS } from '../data/categories.ts';
import type { CategoryId } from '../data/categories.ts';
import { formatYear } from '../data/format.ts';
import { eventSpan, isActiveInYear, toAstronomical, toHistorical } from '../data/spans.ts';
import type { EventSpan } from '../data/spans.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { el } from '../dom.ts';
import { getState, setState, subscribe } from '../state.ts';
import { goToYear } from '../timeline/navigate.ts';

interface Entry {
  category: CategoryId;
  span: EventSpan;
}

export interface Gap {
  /** Events active in the year under the given categories. */
  count: number;
  /** Nearest year before / after `year` with an active event, in historical numbering. */
  prev: number | null;
  next: number | null;
}

/** Pure: how many events are active in `year`, and where the nearest ones are. */
export function nearestEventYears(entries: readonly Entry[], year: number, categories: ReadonlySet<CategoryId>): Gap {
  const y = toAstronomical(Math.round(year));
  let count = 0;
  let prev: number | null = null;
  let next: number | null = null;
  for (const { category, span } of entries) {
    if (!categories.has(category)) continue;
    if (isActiveInYear(span, year)) {
      count += 1;
      continue;
    }
    if (span.end < y && (prev === null || span.end > prev)) prev = span.end;
    if (span.start > y && (next === null || span.start < next)) next = span.start;
  }
  return { count, prev: prev === null ? null : toHistorical(prev), next: next === null ? null : toHistorical(next) };
}

export function initEmptyState(host: HTMLElement, events: readonly HistoricalEvent[]): void {
  const entries: Entry[] = events.map((event) => ({ category: event.category, span: eventSpan(event) }));

  const box = el('div', 'map-empty');
  box.hidden = true;
  box.setAttribute('role', 'status');
  const text = el('p', 'map-empty__text');
  const actions = el('div', 'map-empty__actions');
  box.append(text, actions);
  host.append(box);

  const button = (label: string, run: () => void): HTMLButtonElement => {
    const b = el('button', 'btn', label);
    b.type = 'button';
    b.addEventListener('click', run);
    return b;
  };

  let timer = 0;
  function render(): void {
    const { currentYear, activeCategories, story, selectedEventId } = getState();
    // With no category ticked (the first-visit default) nothing is meant to show, so say nothing.
    if (story !== null || selectedEventId !== null || activeCategories.size === 0) {
      box.hidden = true;
      return;
    }
    const gap = nearestEventYears(entries, currentYear, activeCategories);
    if (gap.count > 0) {
      box.hidden = true;
      return;
    }
    const filtered = activeCategories.size < CATEGORY_IDS.length;
    text.textContent = filtered
      ? `No events in ${formatYear(currentYear, true)} for these filters.`
      : `Nothing is recorded for ${formatYear(currentYear, true)}.`;
    const buttons: HTMLButtonElement[] = [];
    if (filtered) buttons.push(button('Clear filters', () => setState({ activeCategories: new Set(CATEGORY_IDS) })));
    if (gap.prev !== null) {
      const to = gap.prev;
      buttons.push(button(`← ${formatYear(to, true)}`, () => goToYear(to)));
    }
    if (gap.next !== null) {
      const to = gap.next;
      buttons.push(button(`${formatYear(to, true)} →`, () => goToYear(to)));
    }
    actions.replaceChildren(...buttons);
    box.hidden = false;
  }

  // Wait a beat so scrubbing across a quiet stretch does not flash the note.
  const schedule = (): void => {
    window.clearTimeout(timer);
    box.hidden = true;
    timer = window.setTimeout(render, 450);
  };
  schedule();
  subscribe((state, previous) => {
    if (
      state.currentYear !== previous.currentYear ||
      state.activeCategories !== previous.activeCategories ||
      state.story !== previous.story ||
      state.selectedEventId !== previous.selectedEventId
    ) {
      schedule();
    }
  });
}
