import type { CategoryInfo } from './data/categories.ts';
import { STAMP_GRID, stampCuts } from './markerEngraving.ts';

const NS = 'http://www.w3.org/2000/svg';

export function categoryIcon(category: CategoryInfo): SVGSVGElement {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${STAMP_GRID} ${STAMP_GRID}`);
  svg.setAttribute('width', '24');
  svg.setAttribute('height', '24');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  svg.classList.add('category-seal');
  for (const cut of stampCuts(category.shape, category.color, '#fff4dc')) {
    const path = document.createElementNS(NS, 'path');
    path.setAttribute('d', cut.d);
    path.setAttribute('fill', cut.fill ?? 'none');
    path.setAttribute('fill-rule', 'evenodd');
    if (cut.stroke) {
      path.setAttribute('stroke', cut.stroke);
      path.setAttribute('stroke-width', String(cut.width));
      path.setAttribute('stroke-linejoin', 'round');
      path.setAttribute('stroke-linecap', 'round');
    }
    svg.append(path);
  }
  return svg;
}
