import '../styles/scrubLens.css';
import { el } from '../dom.ts';
import { formatYear } from '../data/format.ts';
import { toAstronomical, toHistorical } from '../data/spans.ts';
import type { Scale } from './scale.ts';
import { fineYear, lensRange } from './lensScale.ts';

export function createScrubLens(inner: HTMLElement, rail: HTMLElement, scale: () => Scale, checkpoints: () => ReadonlySet<number>) {
  const element = el('div', 'scrub-lens');
  element.hidden = true;
  element.setAttribute('aria-hidden', 'true'); // The slider already announces the same year.
  const yearText = el('strong', 'scrub-lens__year');
  const ruler = el('div', 'scrub-lens__ruler');
  const ticks = el('div', 'scrub-lens__ticks');
  const cursor = el('i', 'scrub-lens__cursor');
  const ends = el('div', 'scrub-lens__ends');
  const first = el('span'), last = el('span');
  ends.append(first, last);
  ruler.append(ticks, cursor);
  element.append(yearText, ruler, ends);
  inner.append(element);
  const interval = el('span', 'scrub-lens__interval');
  interval.hidden = true;
  interval.setAttribute('aria-hidden', 'true');
  rail.append(interval);

  let fine: { anchor: number; x: number; pixels: number; left: number; fraction: number } | null = null;
  let pixels = 10, left = 0, fraction = .5, gutter = 0;
  let geometry: DOMRect;
  let ink = '';
  let marks: ReadonlySet<number> = new Set();

  function show(year: number, x: number): void {
    if (element.hidden) return;
    const width = Math.max(1, Math.min(242, geometry.width - 4));
    left = fine?.left ?? Math.min(geometry.width - width, Math.max(0, x - geometry.left - width / 2));
    fraction = Math.min(1, Math.max(0, (x - geometry.left - left) / width));
    const mapping = scale();
    // Freeze the graduated strip during a fine drag. Continue the strip at either edge.
    const coarse = lensRange(fine?.anchor ?? year, fine?.fraction ?? fraction, mapping, marks);
    const at = toAstronomical(year);
    const shift = at < coarse.first ? at - coarse.first : at > coarse.last ? at - coarse.last : 0;
    const start = coarse.first + shift, end = coarse.last + shift;
    pixels = width / Math.max(1, coarse.span);
    element.style.left = (gutter + left) + 'px';
    element.style.width = width + 'px';
    const position = ((at - start) / Math.max(1, coarse.span) * 100) + '%';
    cursor.style.left = position;
    element.style.setProperty('--lens-cursor', position);
    yearText.textContent = formatYear(year, true);
    element.toggleAttribute('data-checkpoint', marks.has(year));
    const signature = start + '/' + end;
    if (ink === signature) return;
    ink = signature;
    const rangeStart = mapping.yearToPosition(toHistorical(start));
    interval.style.left = (rangeStart * 100) + '%';
    interval.style.width = ((mapping.yearToPosition(toHistorical(end)) - rangeStart) * 100) + '%';
    const fragment = document.createDocumentFragment();
    for (let a = start; a <= end; a++) {
      const y = toHistorical(a);
      const tick = el('i', 'scrub-lens__tick');
      tick.style.left = (a - start) / Math.max(1, coarse.span) * 100 + '%';
      tick.toggleAttribute('data-major', y % 5 === 0 || Math.abs(y) === 1);
      tick.toggleAttribute('data-checkpoint', marks.has(y));
      fragment.append(tick);
    }
    ticks.replaceChildren(fragment);
    first.textContent = formatYear(toHistorical(start), false);
    last.textContent = formatYear(toHistorical(end), false);
  }

  function begin(year: number, x: number): void {
    fine = null; ink = '';
    marks = checkpoints();
    geometry = inner.getBoundingClientRect();
    const dock = inner.closest<HTMLElement>('.timeline');
    const box = dock?.getBoundingClientRect();
    // Float above the whole control bar when space permits. Its buttons and era stay readable.
    const host = dock && box && box.top > 85 ? dock : inner;
    gutter = host === dock && box ? geometry.left - box.left - host.clientLeft : 0;
    if (element.parentNode !== host) host.append(element);
    interval.hidden = false;
    element.hidden = false;
    delete element.dataset.fine;
    show(year, x);
  }

  return {
    begin, show,
    lock(year: number, x: number) {
      if (fine) return;
      fine = { anchor: year, x, pixels, left, fraction };
      element.dataset.fine = '';
    },
    yearAt(x: number): number | null {
      return fine ? fineYear(fine.anchor, x - fine.x, fine.pixels, scale()) : null;
    },
    close() { fine = null; element.hidden = true; interval.hidden = true; delete element.dataset.fine; },
  };
}
