// The "Culture" section of the filter panel: the Treasures layer toggle and the harvest
// year. Harvest months are shown only for crops whose season has a source; the map leans
// the olive groves brighter through their harvest months.

import { el, externalLink } from '../dom.ts';
import { getState, setState, subscribe } from '../state.ts';

export interface HarvestCrop {
  name: string;
  /** 1-12, inclusive; a range may wrap the year end (11..3 = November to March). */
  from: number;
  to: number;
  sourceTitle: string;
  sourceUrl: string;
  note: string;
}

/** Only crops with a sourced season; more are added as sources are read. */
export const HARVEST: readonly HarvestCrop[] = [
  {
    name: 'Olives',
    from: 10,
    to: 12,
    sourceTitle: 'Olive (Wikipedia)',
    sourceUrl: 'https://en.wikipedia.org/wiki/Olive',
    note: 'Harvested in the autumn, from October onwards; the backbone crop of the hill country.',
  },
  {
    name: 'Jaffa oranges',
    from: 11,
    to: 3,
    sourceTitle: 'Jaffa orange (Wikipedia)',
    sourceUrl: 'https://en.wikipedia.org/wiki/Jaffa_orange',
    note: 'Picked between November and March on the coastal plain.',
  },
];

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function inSeason(crop: HarvestCrop, month: number): boolean {
  return crop.from <= crop.to ? month >= crop.from && month <= crop.to : month >= crop.from || month <= crop.to;
}

export function initCultureSection(slot: HTMLElement): void {
  const heading = el('h3', 'filters__legend', 'Culture');

  // Treasures toggle.
  const label = el('label', 'filters__row');
  const checkbox = el('input');
  checkbox.type = 'checkbox';
  checkbox.checked = getState().treasures;
  label.append(checkbox, el('span', 'filters__name', 'Treasures: what each place is known for'));
  const note = el(
    'p',
    'filters__note',
    'Knafeh and soap in Nablus, oranges in Yafa, glass in al-Khalil, weaving in al-Majdal, tatreez across the districts. Tap a label for the place card; every claim lists its source there.',
  );
  checkbox.addEventListener('change', () => setState({ treasures: checkbox.checked }));
  subscribe((state, previous) => {
    if (state.treasures !== previous.treasures) checkbox.checked = state.treasures;
  });

  // Harvest year.
  const harvestHead = el('p', 'filters__name', 'The harvest year');
  const months = el('div', 'harvest__months');
  months.setAttribute('role', 'group');
  months.setAttribute('aria-label', 'Pick a month to see what is harvested');
  const crops = el('ul', 'card__list harvest__crops');
  const buttons: HTMLButtonElement[] = [];

  function renderCrops(): void {
    const month = getState().harvestMonth;
    crops.replaceChildren();
    buttons.forEach((b, i) => b.setAttribute('aria-pressed', month === i + 1 ? 'true' : 'false'));
    if (month === null) {
      crops.append(el('li', 'card__muted', 'Pick a month. Only crops with a sourced season are listed; more will be added.'));
      return;
    }
    const now = HARVEST.filter((crop) => inSeason(crop, month));
    if (now.length === 0) {
      crops.append(el('li', 'card__muted', 'Nothing in the sourced list is harvested this month (yet).'));
      return;
    }
    for (const crop of now) {
      const item = el('li');
      item.append(el('strong', '', `${crop.name}: `), crop.note, ' ');
      item.append(externalLink(crop.sourceUrl, crop.sourceTitle));
      crops.append(item);
    }
  }

  MONTHS.forEach((name, i) => {
    const b = el('button', 'harvest__month', name);
    b.type = 'button';
    b.setAttribute('aria-pressed', 'false');
    b.addEventListener('click', () => {
      const month = getState().harvestMonth === i + 1 ? null : i + 1;
      setState({ harvestMonth: month });
    });
    buttons.push(b);
    months.append(b);
  });

  renderCrops();
  subscribe((state, previous) => {
    if (state.harvestMonth !== previous.harvestMonth) renderCrops();
  });

  slot.append(heading, label, note, harvestHead, months, crops);
}
