// Display form of transliterated place names: a name that STARTS with the Arabic article
// ("al-Majdal", "ash-Shaykh Muwannis") is shown with the article capitalized ("Al-Majdal"),
// while the article stays lowercase inside a name ("Dayr al-Qassi") and in running prose.
// The stored data keeps the Palestine Remembered spellings (docs/place-names.md); this is
// applied once, right after the data files load.

/** The article and its sun-letter assimilations, hyphenated, at the very start of the name. */
const LEADING_ARTICLE = /^(a(?:l|n|r|s|sh|d|dh|z|t|th))-(?=\p{L})/u;

/** "al-Majdal" -> "Al-Majdal"; leaves "Dayr al-Qassi", "Acre" and Arabic script untouched. */
export function capitalizeArticle(name: string): string {
  return name.replace(LEADING_ARTICLE, (article) => (article[0] ?? '').toUpperCase() + article.slice(1));
}
