import { categoryIcon } from '../categoryIcon.ts';
import { CATEGORIES } from '../data/categories.ts';
import { eventSpan } from '../data/spans.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { el } from '../dom.ts';
import { getState } from '../state.ts';
import { openScene } from './navigate.ts';
import type { EraId } from '../data/eras.ts';

export function createEraEntries(events: readonly HistoricalEvent[]) {
  const element = el('div', 'era-entries');
  const ordered = events.map(event => ({ event, year: eventSpan(event).start }))
    .sort((a, b) => a.year - b.year);

  function select(id: string | null): void {
    for (const button of element.querySelectorAll('button')) {
      if (id && button.dataset.event === id) button.setAttribute('aria-current', 'true');
      else button.removeAttribute('aria-current');
    }
  }
  function update(era: EraId): void {
    const state = getState();
    const entries = state.timelineZoom && !state.story ? ordered.filter(({ event }) =>
      event.era === era && (state.activeCategories.size === 0 || state.activeCategories.has(event.category)) &&
      (state.threadEvents === null || state.threadEvents.includes(event.id))) : [];
    element.hidden = entries.length === 0;
    element.replaceChildren(...entries.map(({ event }) => {
      const button = el('button');
      const category = CATEGORIES.find(c => c.id === event.category);
      if (category) button.append(categoryIcon(category));
      button.append(el('span', 'era-entries__title', event.title));
      button.type = 'button';
      button.title = event.title;
      button.dataset.event = event.id;
      button.addEventListener('click', () => openScene(event));
      return button;
    }));
    element.scrollLeft = 0;
    select(state.selectedEventId);
  }

  return { element, update, select };
}
