// The phone chrome menu: on small screens the utility buttons (Sources, language, Share,
// theme, About, Myths) collapse behind one toggle; on wide screens CSS shows them inline
// and hides the toggle. State lives in data-open on the actions container.

export function initMenu(toggle: HTMLElement, menu: HTMLElement, host: HTMLElement): void {
  const set = (open: boolean): void => {
    if (open) host.setAttribute('data-open', '');
    else host.removeAttribute('data-open');
    toggle.setAttribute('aria-expanded', String(open));
  };

  // The same controls move with the viewport, preserving handlers, names and tab order.
  const narrow = matchMedia('(max-width: 640px)');
  const follow = document.getElementById('follow-button');
  const story = document.getElementById('story-button');
  const filters = document.getElementById('filters-button');
  const arrange = (): void => {
    if (!follow || !story || !filters) return;
    const focused = document.activeElement;
    if (narrow.matches) menu.prepend(follow, story);
    else filters.before(follow, story);
    if (focused instanceof HTMLElement && (focused === follow || focused === story)) {
      (narrow.matches && !host.hasAttribute('data-open') ? toggle : focused).focus({ preventScroll: true });
    }
  };
  arrange();
  narrow.addEventListener('change', arrange);
  toggle.addEventListener('click', () => set(!host.hasAttribute('data-open')));

  // Choosing an action closes the menu (the action's own handler has already run by then).
  menu.addEventListener('click', (e) => {
    if (e.target instanceof Element && e.target.closest('button')) set(false);
  });

  document.addEventListener('pointerdown', (e) => {
    if (!host.hasAttribute('data-open')) return;
    if (e.target instanceof Node && (menu.contains(e.target) || toggle.contains(e.target))) return;
    set(false);
  });

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape' || !host.hasAttribute('data-open')) return;
    set(false);
    toggle.focus();
  });
}
