// "On this day": events whose dateStart has day precision and matches today's month and
// day. Shown at the top of the event list view, and used by the About dialog's line.

import { formatEventDate } from '../data/format.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { parseHistDate } from '../data/dates.ts';
import { el } from '../dom.ts';
import { selectEvent } from '../timeline/navigate.ts';

export function eventsOnThisDay(events: readonly HistoricalEvent[], today: Date = new Date()): HistoricalEvent[] {
  const month = today.getMonth() + 1;
  const day = today.getDate();
  return events.filter((event) => {
    if (event.datePrecision !== 'day') return false;
    const date = parseHistDate(event.dateStart);
    return date !== null && date.month === month && date.day === day;
  });
}

/** A small section listing today's anniversaries; nothing is rendered on quiet days. */
export function onThisDaySection(events: readonly HistoricalEvent[]): HTMLElement | null {
  const today = eventsOnThisDay(events);
  if (today.length === 0) return null;
  const section = el('section', 'on-this-day');
  const heading = el('h3', '', 'On this day');
  heading.id = 'on-this-day-title';
  section.setAttribute('aria-labelledby', heading.id);
  const list = el('ul', 'card__list');
  for (const event of today) {
    const item = el('li');
    const go = el('button', 'link-button', event.title);
    go.type = 'button';
    go.addEventListener('click', () => selectEvent(event));
    item.append(go, el('span', 'card__muted', ` — ${formatEventDate(event)}`));
    list.append(item);
  }
  section.append(heading, list);
  return section;
}
