// A small hook so the timeline can show a running story's checkpoints and jump between
// steps without knowing anything about the story module. initStory() registers the real
// implementation (like src/map/camera.ts does for the camera).

export interface StoryCheckpoint {
  /** Step number, 1..N (0 is the intro and gets no checkpoint). */
  step: number;
  /** Historical year of the step's event. */
  year: number;
  title: string;
}

/** A story as the film needs it: its words and where each step sits in time. */
export interface StoryDescription {
  id: string;
  title: string;
  intro: string;
  steps: { title: string; caption: string; year: number }[];
}

export interface StoryControls {
  jump(step: number): void;
  checkpoints(storyId: string): StoryCheckpoint[];
  /** Starts a story at a step (0 is the introduction) even when none is running. */
  start(storyId: string, step: number): void;
  describe(storyId: string): StoryDescription | null;
  /** The story shown first (the short tour), if there are any stories. */
  firstId(): string | null;
}

let controls: StoryControls | null = null;

export function registerStoryControls(impl: StoryControls): void {
  controls = impl;
}

export function jumpToStoryStep(step: number): void {
  controls?.jump(step);
}

export function storyCheckpoints(storyId: string): StoryCheckpoint[] {
  return controls?.checkpoints(storyId) ?? [];
}

export function startStory(storyId: string, step = 0): void {
  controls?.start(storyId, step);
}

export function describeStory(storyId: string): StoryDescription | null {
  return controls?.describe(storyId) ?? null;
}

export function firstStoryId(): string | null {
  return controls?.firstId() ?? null;
}
