// Timeline bar: era presets, big year readout, play controls, density sparkline, scrubber
// with ticks, and a live region. Modules: scale.ts (non-linear scale), slider.ts, ticks.ts,
// sparkline.ts, eraBar.ts, playback.ts.

import { lensCheckpoints } from './lensCheckpoints.ts';
import { createCheckpointRail } from './checkpointRail.ts';
import { mountChronicleDock } from './chronicleDock.ts';
import type { ResolvedPath } from '../data/pathTypes.ts';
import { formatYear } from '../data/format.ts';
import { el } from '../dom.ts';
import { icon } from '../icons.ts';
import type { EraInfo } from '../data/eras.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { getState, setState, subscribe } from '../state.ts';
import { createEraEntries } from './eraEntries.ts';
import { createEraBar } from './eraBar.ts';
import { cancelYearAnimation, dismissScene, initNavigation } from './navigate.ts';
import { createPlayback } from './playback.ts';
import type { Speed } from './playback.ts';
import type { Scale } from './scale.ts';
import { createEraScale } from './scale.ts';
import { jumpToStoryStep, storyCheckpoints } from '../story/controls.ts';
import { createSlider } from './slider.ts';
import { createSparkline, densityBuckets } from './sparkline.ts';
import { computeTicks } from './ticks.ts';

function eraRange(era: EraInfo): string {
  const end = era.end === null ? 'the present' : formatYear(era.end, true);
  return `${formatYear(era.start, true)} to ${end}`;
}

export function initTimeline(container: HTMLElement, events: readonly HistoricalEvent[], scale: Scale, paths: readonly ResolvedPath[]): void {
  container.replaceChildren();
  initNavigation(scale);

  const eraBar = createEraBar(() => setState({ timelineZoom: !getState().timelineZoom }));
  const playback = createPlayback(scale, events);
  const sparkline = createSparkline();

  const slider = createSlider({
    ...lensCheckpoints(events, year => checkpoints.chooseYear(year)),
    scale,
    onInput: (year) => setState({ currentYear: year, activeEra: scale.eraAt(year).id }),
    onScrubChange: (isScrubbing) => setState({ isScrubbing }),
    onUserControl: () => {
      cancelYearAnimation();
      dismissScene();
      if (getState().story !== null && getState().dimOthers) setState({ dimOthers: false });
      if (getState().isPlaying) setState({ isPlaying: false });
    },
  });

  // The plaque follows the same scale as the geographic scenes.
  const cartouche = el('div', 'year-cartouche');

  const yearText = el('span', 'year-cartouche__year');
  cartouche.setAttribute('aria-hidden', 'true');
  cartouche.append(yearText);
  slider.inner.append(cartouche);

  const playButton = el('button', 'btn play-button');
  playButton.type = 'button';
  playButton.addEventListener('click', () => { dismissScene(); playback.toggle(); });

  const speed = el('select', 'speed-select');
  speed.setAttribute('aria-label', 'Playback speed');
  for (const value of [1, 2, 4] as const) {
    const option = el('option', '', `${value}x`);
    option.value = String(value);
    speed.append(option);
  }
  speed.addEventListener('change', () => playback.setSpeed(Number(speed.value) as Speed));

  const zoomButton = el('button', 'btn zoom-button', 'Era zoom');
  zoomButton.type = 'button';
  zoomButton.title = 'Stretch the track over the current era for finer scrubbing';
  zoomButton.addEventListener('click', () => setState({ timelineZoom: !getState().timelineZoom }));

  const sparkWrap = el('div', 'spark');
  sparkWrap.append(sparkline.element);

  const ticks = el('div', 'ticks');
  ticks.setAttribute('aria-hidden', 'true');
  slider.inner.append(ticks);

  const marks = el('div', 'marks');
  marks.setAttribute('role', 'group'); // an aria-label needs a role to be valid
  marks.setAttribute('aria-label', 'Story checkpoints');
  slider.inner.append(marks);


  let scaleNow: Scale = scale;

  const live = el('div', 'sr-only');
  live.setAttribute('role', 'status');
  live.setAttribute('aria-live', 'polite');

  const entries = createEraEntries(events);
  const checkpoints = createCheckpointRail(events, paths, () => scaleNow);
  const eraText = mountChronicleDock(container, { play: playButton, speed, zoom: zoomButton,
    eras: eraBar.element, spark: sparkWrap, spine: slider.spine, stops: checkpoints.element,
    entries: entries.element, live });
  const refreshEntries = (): void => entries.update(scale.eraAt(getState().currentYear).id);
  refreshEntries();

  // --- Rendering -------------------------------------------------------------------------

  function renderTicks(): void {
    const width = slider.inner.clientWidth;
    ticks.replaceChildren(
      ...computeTicks(scaleNow, width).map((tick) => {
        const node = el('span', tick.label === null ? 'tick' : 'tick tick--major');
        node.style.left = `${tick.pos * 100}%`;
        if (tick.label !== null) node.append(el('span', 'tick__label', tick.label));
        return node;
      }),
    );
  }

  function renderSparkline(): void {
    sparkline.update(densityBuckets(events, scaleNow, getState().activeCategories));
  }

  function renderYear(): void {
    const { currentYear } = getState();
    const era = scale.eraAt(currentYear);
    yearText.textContent = formatYear(currentYear, true);
    eraText.textContent = era.label;
    // The rail fills to the position of the current year.
    const pos = scaleNow.yearToPosition(currentYear) * 100;

    slider.inner.style.setProperty('--atlas-time', `${pos}%`);
    slider.setYear(currentYear, `${formatYear(currentYear, true)}, ${era.label} era`);
    eraBar.setActive(era.id);
  }

  function renderPlay(): void {
    const playing = getState().isPlaying;
    playButton.replaceChildren(icon(playing ? 'pause' : 'play'));
    playButton.setAttribute('aria-label', playing ? 'Pause timeline playback' : 'Play timeline');
  }

  function renderMarks(): void {
    const progress = getState().story;
    if (!progress || progress.step === 0) {
      marks.replaceChildren();
      return;
    }
    marks.replaceChildren(
      ...storyCheckpoints(progress.id).flatMap((cp) => {
        if (cp.year < scaleNow.minYear || cp.year > scaleNow.maxYear) return [];
        const pos = scaleNow.yearToPosition(cp.year);
        const dot = el('button', cp.step === progress.step ? 'mark mark--active' : 'mark');
        dot.type = 'button';
        dot.dataset.year = String(cp.year);
        if (cp.step === progress.step) dot.setAttribute('aria-current', 'step');
        dot.style.left = `${pos * 100}%`;
        dot.setAttribute('aria-label', `Story step ${cp.step}: ${cp.title}, ${formatYear(cp.year, true)}`);
        dot.addEventListener('click', () => jumpToStoryStep(cp.step));
        return [dot];
      }),
    );
  }

  function renderZoom(): void {
    const zoomed = getState().timelineZoom;
    zoomButton.setAttribute('aria-pressed', zoomed ? 'true' : 'false');
    zoomButton.textContent = zoomed ? 'Whole timeline' : 'Era zoom';
  }

  function applyScale(): void {
    const zoomed = getState().timelineZoom;
    scaleNow = zoomed ? createEraScale(scale.eraAt(getState().currentYear), scale.maxYear) : scale;
    slider.setScale(scaleNow);
    checkpoints.update();
    renderZoom();
    renderTicks();
    renderSparkline();
    renderYear();
    renderMarks();
  }

  let announceTimer = 0;
  function announceEra(): void {
    window.clearTimeout(announceTimer);
    announceTimer = window.setTimeout(() => {
      const era = scale.eraAt(getState().currentYear);
      live.textContent = `${era.label} era, ${eraRange(era)}`;
    }, 350);
  }

  renderYear();
  renderPlay();
  renderSparkline();
  renderZoom();
  renderMarks();
  // One tick rebuild per frame at most: a resize can fire several times in a row.
  let ticksFrame = 0;
  new ResizeObserver(() => {
    if (ticksFrame !== 0) return;
    ticksFrame = window.requestAnimationFrame(() => {
      ticksFrame = 0;
      renderTicks();
    });
  }).observe(slider.inner);
  renderTicks();

  // The panel and map sit above the bar, so tell CSS how tall it really is.
  new ResizeObserver(() => {
    document.documentElement.style.setProperty('--timeline-h', `${container.offsetHeight}px`);
  }).observe(container);

  subscribe((state, previous) => {
    if (state.currentYear !== previous.currentYear) {
      renderYear();
      if (scale.eraAt(state.currentYear).id !== scale.eraAt(previous.currentYear).id) {
        announceEra();
        if (state.timelineZoom) applyScale();
      }
    }
    if (state.timelineZoom !== previous.timelineZoom) applyScale();
    if (state.activeEra !== previous.activeEra || state.timelineZoom !== previous.timelineZoom ||
        state.activeCategories !== previous.activeCategories || state.story !== previous.story || state.threadEvents !== previous.threadEvents) refreshEntries();
    if (state.selectedEventId !== previous.selectedEventId) entries.select(state.selectedEventId);
    if (state.story !== previous.story) renderMarks();
    if (state.isPlaying !== previous.isPlaying) renderPlay();
    if (state.activeCategories !== previous.activeCategories) {
      renderSparkline();
      playback.refreshEvents();
    }
    // Opening an event pauses playback.
    if (state.selectedEventId !== null && state.selectedEventId !== previous.selectedEventId && state.isPlaying) {
      setState({ isPlaying: false });
    }
  });
}
