import { formatYear } from '../data/format.ts';
import { el } from '../dom.ts';
import { icon } from '../icons.ts';
import { getState, subscribe } from '../state.ts';
import { createChapters } from './chapters.ts';
import type { FilmChapter } from './chapters.ts';

export interface CardAction {
  label: string;
  primary?: boolean;
  run(): void;
}

export interface CardView {
  kicker: string;
  title: string;
  sub?: string;
  text?: string;
  actions?: CardAction[];
}

export interface FilmActions {
  prev(): void;
  next(): void;
  toggle(): void;
  sound(): void;
  exit(): void;
  jump(beat: number): void;
  browse(): void;
}

const BACKGROUND_CONTROLS = [
  '.topbar', '.timeline', '.story', '.panel', '.coach', '.skip-link', '.event-list',
  '.maplibregl-canvas-container', '.maplibregl-ctrl-top-right', '.maplibregl-ctrl-bottom-left',
].join(', ');

export function createFilmUi(actions: FilmActions) {
  const root = el('div', 'film');
  root.hidden = true;
  root.tabIndex = -1;
  root.setAttribute('role', 'region');
  root.setAttribute('aria-label', 'Film');

  const top = el('div', 'film__mast');
  const year = el('p', 'film__year');
  year.setAttribute('aria-hidden', 'true');
  const pausedLabel = el('span', 'film__paused', 'Paused');
  pausedLabel.hidden = true;
  top.append(year, pausedLabel);

  const caption = el('div', 'film__caption');
  caption.setAttribute('aria-live', 'polite');
  caption.setAttribute('aria-atomic', 'true');
  const chapter = el('p', 'film__chapter');
  const heading = el('h2', 'film__heading');
  const text = el('p', 'film__text');
  for (const entry of [heading, text]) {
    entry.dir = 'auto';
    entry.setAttribute('data-no-translate', '');
  }
  caption.append(chapter, heading, text);

  const veil = el('div', 'film__veil');
  veil.inert = true;
  const card = el('div', 'film__card');
  veil.append(card);

  const progress = el('div', 'film__progress');
  progress.setAttribute('aria-hidden', 'true');
  const transport = el('div', 'film__transport');
  const controls = el('div', 'film__controls');
  const chapters = createChapters(actions.jump, actions.browse);

  const button = (label: string, name: Parameters<typeof icon>[0], run: () => void): HTMLButtonElement => {
    const b = el('button', 'film__button');
    b.type = 'button';
    b.setAttribute('aria-label', label);
    b.title = label;
    b.append(icon(name, 20));
    b.addEventListener('click', run);
    return b;
  };
  const prev = button('Previous', 'prev', actions.prev);
  const pause = button('Pause', 'pause', actions.toggle);
  pause.classList.add('film__button--play');
  const next = button('Next', 'next', actions.next);
  const sound = button('Turn sound on', 'soundOff', actions.sound);
  sound.setAttribute('aria-pressed', 'false');
  const exit = button('Exit the film', 'close', actions.exit);
  controls.append(prev, pause, next);
  const utilities = el('div', 'film__utilities');
  utilities.append(sound, exit);
  transport.append(progress, chapters.toggle, controls, utilities);
  root.append(top, caption, veil, chapters.panel, transport);

  const syncYear = (): void => {
    year.textContent = formatYear(getState().currentYear, true);
  };
  subscribe((state, previous) => {
    if (state.currentYear !== previous.currentYear && !root.hidden) syncYear();
  });

  let locked: HTMLElement[] = [];
  let creditsObserver: ResizeObserver | null = null;
  return {
    element: root,
    chaptersOpen: chapters.isOpen,
    closeChapters: () => chapters.close(),
    open(items: FilmChapter[]) {
      root.hidden = false;
      chapters.load(items);
      syncYear();
      document.documentElement.dataset['film'] = '';
      locked = Array.from(document.querySelectorAll<HTMLElement>(BACKGROUND_CONTROLS)).filter((item) => !item.inert);
      for (const item of locked) item.inert = true;
      const credits = document.querySelector('.maplibregl-ctrl-bottom-right');
      if (credits) {
        creditsObserver = new ResizeObserver(() => {
          root.style.setProperty('--film-credit-height', `${credits.getBoundingClientRect().height}px`);
        });
        creditsObserver.observe(credits);
      }
      root.focus({ preventScroll: true });
    },
    close() {
      chapters.close(false);
      creditsObserver?.disconnect();
      creditsObserver = null;
      root.style.removeProperty('--film-credit-height');
      root.hidden = true;
      delete document.documentElement.dataset['film'];
      caption.classList.remove('film__caption--on');
      veil.classList.remove('film__veil--on');
      veil.inert = true;
      for (const item of locked) item.inert = false;
      locked = [];
    },
    showBeat(index: number, total: number, ended: boolean) {
      prev.disabled = index === 0;
      next.disabled = index === total - 1;
      pause.disabled = ended;
      chapters.mark(index);
    },
    card(view: CardView | null) {
      if (view === null) {
        veil.classList.remove('film__veil--on');
        veil.inert = true;
        return;
      }
      const title = el('h2', 'film__title', view.title);
      title.dir = 'auto';
      title.setAttribute('data-no-translate', '');
      card.replaceChildren(el('p', 'film__kicker', view.kicker), title);
      if (view.sub) card.append(el('p', 'film__sub', view.sub));
      if (view.text) {
        const body = el('p', 'film__card-text', view.text);
        body.dir = 'auto';
        body.setAttribute('data-no-translate', '');
        card.append(body);
      }
      if (view.actions?.length) {
        const row = el('div', 'film__actions');
        for (const a of view.actions) {
          const b = el('button', a.primary ? 'btn btn--primary' : 'btn', a.label);
          b.type = 'button';
          b.addEventListener('click', a.run);
          row.append(b);
        }
        card.append(row);
      }
      veil.inert = false;
      veil.classList.remove('film__veil--on');
      card.querySelector<HTMLButtonElement>('.btn--primary')?.focus({ preventScroll: true });
    },
    caption(view: { chapter: string; heading: string; text: string } | null) {
      if (view === null) {
        caption.classList.remove('film__caption--on');
        return;
      }
      chapter.textContent = view.chapter;
      heading.textContent = view.heading;
      text.textContent = view.text;
      caption.classList.add('film__caption--on');
    },
    progress(done: number, total: number) {
      if (progress.childElementCount !== total) {
        progress.replaceChildren(...Array.from({ length: total }, () => el('span', 'film__tick')));
      }
      for (const [i, tick] of Array.from(progress.children).entries()) {
        tick.classList.toggle('film__tick--done', i < done);
        tick.classList.toggle('film__tick--current', i === done);
      }
    },
    setPaused(paused: boolean) {
      pausedLabel.hidden = !paused;
      pause.replaceChildren(icon(paused ? 'play' : 'pause', 20));
      pause.setAttribute('aria-label', paused ? 'Resume' : 'Pause');
      pause.title = paused ? 'Resume' : 'Pause';
    },
    setSound(on: boolean) {
      sound.replaceChildren(icon(on ? 'sound' : 'soundOff', 20));
      sound.setAttribute('aria-pressed', String(on));
      sound.setAttribute('aria-label', on ? 'Turn sound off' : 'Turn sound on');
      sound.title = on ? 'Turn sound off' : 'Turn sound on';
    },
  };
}
