// The film's sound, made in the browser with the Web Audio API: a low drone under the film, a soft
// paper rustle as a caption arrives, and a seal thump on title cards. Nothing is downloaded and
// nothing is licensed. It is OFF until the reader turns it on (the choice is remembered), and the
// audio engine is not even created until then.

export type Cue = 'paper' | 'seal';

export interface FilmSound {
  enabled(): boolean;
  /** Turns sound on or off and remembers it. Must be called from a click or key press the first time. */
  setEnabled(on: boolean): void;
  /** Fades the drone in (call when the film starts) or out (when it ends). */
  drone(on: boolean): void;
  cue(name: Cue): void;
}

const KEY = 'film-sound';

function saved(): boolean {
  try {
    return window.localStorage.getItem(KEY) === '1';
  } catch {
    return false;
  }
}

export function createFilmSound(): FilmSound {
  let on = saved();
  let ctx: AudioContext | null = null;
  let master: GainNode | null = null;
  let droneGain: GainNode | null = null;
  let droneNodes: OscillatorNode[] = [];
  let wantDrone = false;

  function engine(): AudioContext | null {
    if (ctx) return ctx;
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return null;
    ctx = new Ctor();
    master = ctx.createGain();
    master.gain.value = 0.9;
    master.connect(ctx.destination);
    return ctx;
  }

  /** One second of white noise, reused for the paper and the seal. */
  let noise: AudioBuffer | null = null;
  function noiseBuffer(c: AudioContext): AudioBuffer {
    if (noise) return noise;
    noise = c.createBuffer(1, c.sampleRate, c.sampleRate);
    const data = noise.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return noise;
  }

  function startDrone(c: AudioContext): void {
    if (droneGain || !master) return;
    droneGain = c.createGain();
    droneGain.gain.value = 0;
    const filter = c.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    droneGain.connect(filter);
    filter.connect(master);
    // D, A and F: a bare minor colour, each voice a hair out of tune so the chord slowly breathes.
    for (const [hz, detune] of [[73.42, -4], [110, 5], [174.61, -3], [220, 6]] as const) {
      const osc = c.createOscillator();
      osc.type = 'triangle';
      osc.frequency.value = hz;
      osc.detune.value = detune;
      const level = c.createGain();
      level.gain.value = hz < 150 ? 0.5 : 0.22;
      osc.connect(level);
      level.connect(droneGain);
      osc.start();
      droneNodes.push(osc);
    }
    // A very slow swell on the whole drone.
    const lfo = c.createOscillator();
    lfo.frequency.value = 0.07;
    const depth = c.createGain();
    depth.gain.value = 0.008;
    lfo.connect(depth);
    depth.connect(droneGain.gain);
    lfo.start();
    droneNodes.push(lfo);
  }

  function stopDrone(c: AudioContext): void {
    if (!droneGain) return;
    const g = droneGain;
    g.gain.cancelScheduledValues(c.currentTime);
    g.gain.setTargetAtTime(0, c.currentTime, 0.5);
    const nodes = droneNodes;
    droneGain = null;
    droneNodes = [];
    window.setTimeout(() => nodes.forEach((n) => n.stop()), 2500);
  }

  function applyDrone(): void {
    const c = on ? engine() : ctx;
    if (!c) return;
    if (c.state === 'suspended') void c.resume();
    if (on && wantDrone) {
      startDrone(c);
      droneGain?.gain.setTargetAtTime(0.045, c.currentTime, 1.4);
    } else {
      stopDrone(c);
    }
  }

  return {
    enabled: () => on,
    setEnabled(next) {
      on = next;
      try {
        window.localStorage.setItem(KEY, next ? '1' : '0');
      } catch {
        // Storage can be blocked; the choice then lasts for this visit only.
      }
      applyDrone();
    },
    drone(next) {
      wantDrone = next;
      applyDrone();
    },
    cue(name) {
      if (!on) return;
      const c = engine();
      if (!c || !master) return;
      if (c.state === 'suspended') void c.resume();
      const t = c.currentTime;
      const out = master;
      if (name === 'paper') {
        // A short, soft burst of filtered noise.
        const src = c.createBufferSource();
        src.buffer = noiseBuffer(c);
        const band = c.createBiquadFilter();
        band.type = 'bandpass';
        band.frequency.value = 2600;
        band.Q.value = 0.7;
        const g = c.createGain();
        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(0.05, t + 0.04);
        g.gain.exponentialRampToValueAtTime(0.0005, t + 0.38);
        src.connect(band);
        band.connect(g);
        g.connect(out);
        src.start(t, Math.random() * 0.5, 0.45);
      } else {
        // A low thump that drops in pitch, with a touch of noise at the strike.
        const osc = c.createOscillator();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(92, t);
        osc.frequency.exponentialRampToValueAtTime(42, t + 0.32);
        const g = c.createGain();
        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(0.22, t + 0.015);
        g.gain.exponentialRampToValueAtTime(0.0005, t + 0.7);
        osc.connect(g);
        g.connect(out);
        osc.start(t);
        osc.stop(t + 0.75);
        const src = c.createBufferSource();
        src.buffer = noiseBuffer(c);
        const low = c.createBiquadFilter();
        low.type = 'lowpass';
        low.frequency.value = 380;
        const ng = c.createGain();
        ng.gain.setValueAtTime(0.09, t);
        ng.gain.exponentialRampToValueAtTime(0.0005, t + 0.16);
        src.connect(low);
        low.connect(ng);
        ng.connect(out);
        src.start(t, 0, 0.2);
      }
    },
  };
}
