// Era preset buttons above the track. Clicking one animates the handle to the era's start,
// sets the era, and asks the map to fit that era's bounds.

import { ERAS } from '../data/eras.ts';
import type { EraId } from '../data/eras.ts';
import { fitToBounds } from '../map/camera.ts';
import { dismissScene, goToYear } from './navigate.ts';
import { ERA_SHARES } from './scale.ts';

export interface EraBar {
  element: HTMLElement;
  setActive(era: EraId | null): void;
}

export function createEraBar(onActiveClick?: (era: EraId) => void): EraBar {
  const element = document.createElement('div');
  element.className = 'eras';
  element.setAttribute('role', 'group');
  element.setAttribute('aria-label', 'Jump to an era');

  const buttons = new Map<EraId, HTMLButtonElement>();
  for (const era of ERAS) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'era-button';
    button.textContent = era.label;
    button.title = era.label; // the band squeezes long names; the tooltip keeps them readable
    button.style.flexGrow = String(Math.round(ERA_SHARES[era.id] * 1000));
    button.addEventListener('click', () => {
      if (button.getAttribute('aria-current') === 'true' && onActiveClick) {
        onActiveClick(era.id);
        return;
      }
      // The explicit era flight takes over from a checkpoint's return-to-view animation.
      dismissScene();
      requestAnimationFrame(() => fitToBounds(era.bounds));
      goToYear(era.start);
    });
    buttons.set(era.id, button);
    element.append(button);
  }

  let previous: EraId | null | undefined;
  const revealActive = (): void => {
    const button = previous && buttons.get(previous);
    if (!button || element.clientWidth === 0 || element.scrollWidth <= element.clientWidth) return;
    const bar = element.getBoundingClientRect();
    const tab = button.getBoundingClientRect();
    if (tab.left < bar.left || tab.right > bar.right) {
      element.scrollBy({ left: (tab.left + tab.right - bar.left - bar.right) / 2 });
    }
  };
  // Account for the first layout and orientation changes, even when the year stays the same.
  new ResizeObserver(revealActive).observe(element);
  return {
    element,
    setActive(active) {
      if (active === previous) return;
      previous = active;
      for (const [id, button] of buttons) {
        if (id === active) button.setAttribute('aria-current', 'true');
        else button.removeAttribute('aria-current');
      }
      revealActive();
    },
  };
}
