import type { Place, PlaceKind } from '../data/placeTypes.ts';
import { isDistrictCentre } from '../map/districtCentres.ts';
import city from './places/city.webp';
import town from './places/town.webp';
import village from './places/village.webp';
import site from './places/site.webp';
import region from './places/region.webp';
import water from './places/water.webp';
import mountain from './places/mountain.webp';
import settlement from './places/settlement.webp';

export type PlaceArt = PlaceKind | 'settlement';
export const ART: Record<PlaceArt, string> = { city, town, village, site, region, water, mountain, settlement };

export function artFor(place: Pick<Place, 'kind' | 'group'>): PlaceArt {
  return place.group === 'settlement' ? 'settlement' : place.kind;
}

/** A type illustration. The neighboring name and kind provide the accessible description. */
export function placeEmblem(place: Place): HTMLElement {
  const well = document.createElement('span');
  well.className = 'place-emblem';
  if (isDistrictCentre(place.id)) well.classList.add('place-emblem--district');
  well.setAttribute('aria-hidden', 'true');
  const picture = document.createElement('img');
  picture.src = ART[artFor(place)];
  picture.alt = '';
  picture.width = 64;
  picture.height = 64;
  picture.decoding = 'async';
  picture.draggable = false;
  well.append(picture);
  return well;
}
