// Stretch only the blank paper. Rules, corners and the miniature keep their original proportions.
import { drawDistrictRibbon } from './districtRibbon.ts';
import { ART } from '../art/placeArt.ts';
import type { PlaceArt } from '../art/placeArt.ts';
import type { Palette } from './style.ts';
import { luminance, mix } from './color.ts';

export const PLATE_PREFIX = 'look-nameplate-';
export const BASEMAP_PLATE = PLATE_PREFIX + 'context';
export const FOCUS_SUFFIX = '-focus';

export interface Nameplate {
  kind: PlaceArt | 'context';
  focused: boolean;
  design?: 'district' | 'pocket';
}

export function readNameplate(id: string): Nameplate | null {
  if (!id.startsWith(PLATE_PREFIX)) return null;
  const focused = id.endsWith(FOCUS_SUFFIX);
  const key = id.slice(PLATE_PREFIX.length, focused ? -FOCUS_SUFFIX.length : undefined);
  if (key === 'district') return { kind: 'city', focused, design: 'district' };
  if (key === 'village-pocket') return { kind: 'village', focused, design: 'pocket' };
  if (key === 'context') return { kind: key, focused: false };
  return Object.hasOwn(ART, key) ? { kind: key as PlaceArt, focused } : null;
}

const RATIO = 3;
const WIDTH = 92;
const HEIGHT = 40;

function metrics(plate: Nameplate) {
  if (plate.design === 'pocket') return { miniature: 14, plain: false, left: 19, edge: 3 };
  const miniature = plate.kind === 'city' ? 29 : plate.kind === 'town' ? 25 : 21;
  const plain = plate.kind === 'context';
  const left = plain ? 4 : miniature + 9;
  const edge = plain ? 3 : 5;
  return { miniature, plain, left, edge };
}

export function plateOptions(plate: Nameplate) {
  if (plate.design === 'district') {
    const band = (a: number, b: number): [number, number] => [a * RATIO, b * RATIO];
    const content: [number, number, number, number] = [32 * RATIO, 5 * RATIO, 80 * RATIO, 31 * RATIO];
    return { pixelRatio: RATIO, stretchX: [band(32, 80)], stretchY: [band(6, 11), band(26, 31)], content };
  }
  const { miniature, plain, left, edge } = metrics(plate);
  const band = (a: number, b: number): [number, number] => [a * RATIO, b * RATIO];
  const middle = HEIGHT / 2;
  const stretchY = plain ? [band(edge, HEIGHT - edge)] :
    [band(3, middle - miniature / 2), band(middle + miniature / 2, HEIGHT - 3)];
  const content: [number, number, number, number] =
    [left * RATIO, 3 * RATIO, (WIDTH - edge) * RATIO, (HEIGHT - 3) * RATIO];
  return { pixelRatio: RATIO, stretchX: [band(left, WIDTH - edge)], stretchY, content };
}

function outline(g: CanvasRenderingContext2D, x: number, y: number, width: number, height: number, cut: number): void {
  g.beginPath();
  g.moveTo(x + cut, y);
  g.lineTo(x + width - cut, y);
  g.lineTo(x + width, y + cut);
  g.lineTo(x + width, y + height - cut);
  g.lineTo(x + width - cut, y + height);
  g.lineTo(x + cut, y + height);
  g.lineTo(x, y + height - cut);
  g.lineTo(x, y + cut);
  g.closePath();
}

export function drawNameplate(plate: Nameplate, p: Palette, miniatureArt?: HTMLImageElement): ImageData {
  const canvas = document.createElement('canvas');
  canvas.width = WIDTH * RATIO;
  canvas.height = HEIGHT * RATIO;
  const g = canvas.getContext('2d');
  if (!g) throw new Error('2D canvas is not available');
  g.scale(RATIO, RATIO);
  const { plain, miniature, left } = metrics(plate);
  const dark = luminance(p.paper) < 0.5;
  const brass = dark ? '#c29b65' : '#a07948';
  const rim = dark ? '#c8b290' : '#584533';
  if (plate.design === 'district') {
    drawDistrictRibbon(g, p, plate.focused);
    return g.getImageData(0, 0, canvas.width, canvas.height);
  }
  const pocket = plate.design === 'pocket';
  const paper = dark ? mix(p.paper, '#30271f', .34) : mix(p.paper, '#fff2d7', .72);

  outline(g, 1.4, 2.4, WIDTH - 2.8, HEIGHT - 3.1, plain ? 1 : 3);
  g.fillStyle = dark ? '#120f0c' : 'rgba(60,42,24,.32)';
  g.fill();
  outline(g, 1, 1, WIDTH - 2.6, HEIGHT - 3.2, plain ? 1 : 3);
  g.fillStyle = paper;
  g.fill();
  g.lineWidth = plate.focused ? 1.5 : plain || pocket ? .75 : 1;
  g.strokeStyle = plate.focused ? (dark ? '#f1c578' : '#815121') : rim;
  g.stroke();

  if (!plain) {
    const well = left - 3.5;
    const pigment = g.createLinearGradient(0, 3, well, HEIGHT);
    pigment.addColorStop(0, pocket ? mix(paper, brass, .26) : plate.focused ? '#815a36' : '#5f5141');
    pigment.addColorStop(1, pocket ? mix(paper, brass, .42) : plate.focused ? '#483021' : '#392f29');
    g.save();
    g.clip();
    g.fillStyle = pigment;
    g.fillRect(1.4, 1.4, well - 1.4, HEIGHT - 3.6);
    g.fillStyle = brass;
    g.fillRect(well, 1.8, 1, HEIGHT - 4.2);
    g.restore();
    outline(g, 3.1, 3, WIDTH - 6.8, HEIGHT - 7.2, 1.6);
    g.strokeStyle = dark ? '#9f8564' : '#bca581';
    g.lineWidth = .65;
    if (!pocket) g.stroke();
    const x = (well - miniature) / 2 + 1;
    const y = (HEIGHT - miniature) / 2;
    if (miniatureArt?.naturalWidth) {
      g.imageSmoothingQuality = 'high';
      g.drawImage(miniatureArt, x, y, miniature, miniature);
    } else {
      // The label is immediately legible even while the illustrated type mark decodes.
      const cx = well / 2 + 1;
      g.fillStyle = '#dec297';
      g.beginPath();
      g.moveTo(cx, 15); g.lineTo(cx + 4, 20); g.lineTo(cx, 25); g.lineTo(cx - 4, 20);
      g.closePath(); g.fill();
    }
  }
  return g.getImageData(0, 0, canvas.width, canvas.height);
}
