import { isLandEvent, pathPositions, sceneBounds } from '../map/sceneExtent.ts';
import type { ResolvedPath } from '../data/pathTypes.ts';
import type { HistoricalEvent } from '../data/types.ts';

const ns = 'http://www.w3.org/2000/svg';
const point = ([lng, lat]: readonly [number, number]) => [
  ((lng + 180) / 360 * 256 - 151) * 256,
  ((1 - Math.asinh(Math.tan(lat * Math.PI / 180)) / Math.PI) * 128 - 102) * 256,
] as const;

function node<K extends keyof SVGElementTagNameMap>(tag: K, attrs: Record<string, string | number>) {
  const element = document.createElementNS(ns, tag);
  for (const [key, value] of Object.entries(attrs)) element.setAttribute(key, String(value));
  return element;
}

/** A crop of the same local terrain in every scene. Geometry controls its scale and position. */
export function scenePlate(event: HistoricalEvent, paths: readonly ResolvedPath[]): SVGSVGElement {
  const svg = node('svg', { viewBox: '0 0 320 84', preserveAspectRatio: 'xMidYMid slice',
    class: 'scene-plate', 'aria-hidden': 'true', focusable: 'false' });
  const { lng, lat, precision } = event.location;
  const [px, py] = point([lng, lat]);
  const extent = sceneBounds(event.location, paths);
  let cx = px, cy = py;
  let scale = precision === 'approximate' ? 1.25 : 2;
  if (isLandEvent(event.location)) {
    // The companion seal holds the complete outline. This print supplies its surrounding terrain.
    scale = .62;
  } else if (extent) {
    const [w, s] = point(extent[0]), [e, n] = point(extent[1]);
    cx = (w + e) / 2; cy = (n + s) / 2;
    scale = Math.min(2.4, 142 / Math.max(1, e - w), 64 / Math.max(1, s - n));
  }
  const x = (v: number) => 196 + (v - cx) * scale;
  const y = (v: number) => 42 + (v - cy) * scale;
  svg.append(node('image', { href: new URL('art/scene-relief.webp', document.baseURI).href,
    x: x(0), y: y(0), width: 1024 * scale, height: 1280 * scale }));
  const pin = (p: readonly [number, number], r: number) => {
    const [ax, ay] = point(p);
    svg.append(node('circle', { cx: x(ax), cy: y(ay), r, fill: '#f7df9d', stroke: '#46351d', 'stroke-width': 1.4 }));
  };
  for (const path of paths) {
    const d = pathPositions(path).map((p, i) => {
      const [ax, ay] = point(p);
      return (i ? 'L' : 'M') + x(ax).toFixed(2) + ' ' + y(ay).toFixed(2);
    }).join(' ');
    svg.append(node('path', { d, fill: 'none', stroke: '#483420', 'stroke-width': 3.5 }));
    svg.append(node('path', { d, fill: 'none', stroke: '#ffe2a0', 'stroke-width': 1.5,
      'stroke-dasharray': path.shape === 'schematic' ? '3 2' : 'none' }));
    for (const p of path.waypoints) pin([p.lng, p.lat], 2.4);
  }
  if (!paths.length && !isLandEvent(event.location)) {
    const radius = precision === 'approximate' ? 21 : 11;
    svg.append(node('circle', { cx: x(px), cy: y(py), r: radius, fill: '#ffedb9', 'fill-opacity': .12,
      stroke: '#fff2c9', 'stroke-width': 1.3, 'stroke-dasharray': precision === 'approximate' ? '2 3' : 'none' }));
    if (precision !== 'approximate') pin([lng, lat], 3.2);
  }
  return svg;
}
