// Era definitions from docs/SPEC.md section 8. Ids must match the "era" enum in
// public/data/events.schema.json (the validator checks this).
//
// Years use historical numbering: negative = BCE, positive = CE, no year 0.
// Boundaries are inclusive on both ends, so a boundary year (e.g. 1948) can belong to
// either neighbouring era; the event's author picks the one that fits.
// `end: null` means "to the present".

import { HOME_BOUNDS } from './region.ts';
import type { LngLatBox } from './region.ts';

export const ERA_IDS = [
  'ancient',
  'classical',
  'early-islamic',
  'crusader',
  'ayyubid-mamluk',
  'ottoman',
  'british-mandate',
  '1948-1967',
  '1967-1993',
  '1993-present',
] as const;

export type EraId = (typeof ERA_IDS)[number];

export interface EraInfo {
  id: EraId;
  label: string;
  start: number;
  end: number | null;
  /** Where the map looks when this era is chosen. A viewport choice, not a historical claim. */
  bounds: LngLatBox;
  /** Two lines of orientation shown once per visit on entering the era; restates this map's own events. */
  summary?: string;
}

// Every era starts with the home view. Give an era its own box here to change where the map
// goes when that era's button is pressed, e.g. a wider box for an era whose story reaches
// beyond Palestine.
const HOME = HOME_BOUNDS;

export const ERAS: readonly EraInfo[] = [
  { id: 'ancient', label: 'Ancient', start: -3200, end: -332, bounds: HOME, summary: 'Bronze and Iron Age Palestine: the first walled cities, Egyptian and Assyrian records naming the Peleset and Palashtu, and the Philistine coast.' },
  { id: 'classical', label: 'Classical', start: -332, end: 638, bounds: HOME, summary: 'From Alexander to Byzantium: Hellenistic rule, Roman Palaestina, early Christianity, and the three Palestines of late antiquity.' },
  { id: 'early-islamic', label: 'Early Islamic', start: 638, end: 1099, bounds: HOME, summary: 'The Arab conquest brings the province of Jund Filastin: Ramla founded as its capital, the Dome of the Rock and al-Aqsa raised, Umayyad to Fatimid rule.' },
  { id: 'crusader', label: 'Crusader', start: 1099, end: 1187, bounds: HOME, summary: "Crusader states hold Jerusalem and the coast for most of a century, until Salah al-Din's victory at Hittin in 1187." },
  { id: 'ayyubid-mamluk', label: 'Ayyubid-Mamluk', start: 1187, end: 1516, bounds: HOME, summary: 'Ayyubid recovery, the fall of the last Crusader strongholds, and three centuries of Mamluk rule from Cairo.' },
  { id: 'ottoman', label: 'Ottoman', start: 1516, end: 1917, bounds: HOME, summary: "Four Ottoman centuries: the sanjaks of Jerusalem, Nablus and Gaza, Dahir al-Umar's Galilee, then late-era reforms, railways and the press." },
  { id: 'british-mandate', label: 'British Mandate', start: 1917, end: 1948, bounds: HOME, summary: 'British rule under a League of Nations mandate: the Balfour Declaration, growing Zionist settlement, Palestinian revolt, and the road to 1948.' },
  { id: '1948-1967', label: '1948-1967', start: 1948, end: 1967, bounds: HOME, summary: 'The Nakba: Israel declared, war, and mass displacement; armistice lines leave the West Bank with Jordan and Gaza under Egyptian administration.' },
  { id: '1967-1993', label: '1967-1993', start: 1967, end: 1993, bounds: HOME, summary: 'The June 1967 war puts the West Bank, Gaza and East Jerusalem under Israeli occupation; settlements begin, the PLO rises, the First Intifada breaks out.' },
  { id: '1993-present', label: '1993-present', start: 1993, end: null, bounds: HOME, summary: 'The Oslo agreements divide the West Bank into areas; the Second Intifada, the wall, the blockade of Gaza, and the wars since.' },
];

export function eraById(id: EraId): EraInfo {
  const era = ERAS.find((e) => e.id === id);
  if (!era) throw new Error(`Unknown era: ${id}`);
  return era;
}
