import type { MarkerShape } from './data/categories.ts';
import { shapeOutline } from './data/shapes.ts';

// Common die for the on-map enamel seals, filter keys, search results and time rail.
// Paths use a 28-unit view box. The small cutouts are kept open at phone scale.
export const STAMP_GRID = 28;

interface Cut {
  d: string;
  fill?: string;
  stroke?: string;
  width?: number;
}

const MOTIF: Record<Exclude<MarkerShape, 'ring-chevron'>, readonly [string, string]> = {
  // Charter, with a folded corner and wax seal.
  square: ['M8 6.8h9l3 3.2v6.4h-2v-5.8h-3.4V8.7H10v10.5h4v1.9H8Z M17.9 15.4a2.3 2.3 0 1 0 .1 0Zm-1.8 4 1.3.6 1.5-.5.7 2.3-2-.7-1.7.7Z', 'M11.7 12h3.9m-3.9 2.5h3'],
  // Opposing pennants, kept apart by the diagonal.
  diamond: ['M7.6 10.8l6.1.4-2.6 2.9 2.1 1.1-4.2.4Zm12.8 6.4-6.1-.4 2.6-2.9-2.1-1.1 4.2-.4Z', 'm8 9.5.8 8.7m11.2.2-.8-8.6'],
  // Cut-paper rosette.
  circle: ['M14 5.7l2.1 4.6 4.7-1.6-1.6 4.7 3.5 1.7-4.5 1.4.8 4.8-4.9-2.3-4.8 2.2.8-4.6-4.3-1.6 3.3-1.7-1.3-4.5 4.4 1.5Z M14 11.9l-2.5 2.6 2.5 2.5 2.5-2.5Z', ''],
  // A group of people.
  triangle: ['M14 10.6a2.1 2.1 0 1 1 0 4.2 2.1 2.1 0 0 1 0-4.2Zm-3.8 9.5q.2-4.5 3.8-4.5t3.8 4.5Z M8.7 15a1.45 1.45 0 1 1 0 2.9 1.45 1.45 0 0 1 0-2.9Zm10.6 0a1.45 1.45 0 1 1 0 2.9 1.45 1.45 0 0 1 0-2.9Z', 'M7.5 19.9h1.3m10.4 0h1.3'],
  // Recessed architectural arch.
  octagon: ['M7.3 21v-2.5h1.8v-5c0-2.6 2.2-4.4 4.9-7 2.7 2.6 4.9 4.4 4.9 7v5h1.8V21Z M11.5 18.6h5v-5.1q0-1.5-2.5-3.8-2.5 2.3-2.5 3.8Z', 'M10.5 22h7'],
  // Branch, broad leaf and fruit.
  hexagon: ['M13.7 13.9C12 8 15.2 6 20.2 6c-.6 4.4-2.2 7.2-6.5 7.9Zm-1.2 3.5C7.2 17 6.4 14 6.6 10.5c4.4.4 6.3 2.8 5.9 6.9Zm5.1-1.7c3.3-1.4 4.3 1.9 1.8 4.1-2.6 1.8-4.4-1.4-1.8-4.1Z','M9.5 22q4-4.3 6.2-11'],
  // Three adjacent plots.
  pentagon: ['M6.5 13.8 14 8.4l7.5 4.3-7.4 6Z M9.5 14l4.4 2.6 1.6-1.4-4.4-2.5Z', 'm7.3 17 6.9 4 6.7-5.2'],
};

function outline(shape: MarkerShape, r: number): string {
  const figure = shapeOutline(shape, STAMP_GRID / 2, r);
  if (figure.kind === 'circle') return `M${14-r} 14a${r} ${r} 0 1 1 ${2*r} 0a${r} ${r} 0 1 1 ${-2*r} 0Z`;
  return 'M' + figure.points.map(([x,y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join('L') + 'Z';
}

export function stampCuts(shape: MarkerShape, enamel: string, halo: string): Cut[] {
  if (shape === 'ring-chevron') return [
    { d: outline(shape,10.9), fill: halo, stroke: '#58412c', width: .95 },
    { d: outline(shape,8.7), fill: 'none', stroke: enamel, width: 2.6 },
    { d: 'm11.7 8.2 7.1 5.8-7.1 5.8v-3L15 14l-3.3-2.8Z', fill: enamel },
  ];
  const [solid, lines] = MOTIF[shape];
  const cuts: Cut[] = [
    { d: outline(shape,10.9), fill: '#553f2e', stroke: halo, width: 1.85 },
    { d: outline(shape,9.55), fill: enamel, stroke: '#d9b57d', width: .85 },
  ];
  if (solid) cuts.push({ d: solid, fill: '#fff1ce' });
  if (lines) cuts.push({ d: lines, fill: 'none', stroke: '#fff1ce', width: 1.45 });
  return cuts;
}
