import { formatEventDate, formatYear } from '../data/format.ts';
import { eventStartYear } from '../data/spans.ts';
import type { HistoricalEvent } from '../data/types.ts';
import type { Scale } from './scale.ts';

export interface StopGroup {
  position: number;
  events: HistoricalEvent[];
}

/** Anchor each group to an actual date. Nearby dates share a picker, never a guessed year. */
export function groupStops(ordered: readonly HistoricalEvent[], scale: Scale, width: number, gap: number): StopGroup[] {
  const groups: StopGroup[] = [];
  for (const event of ordered) {
    const year = eventStartYear(event);
    if (year < scale.minYear || year > scale.maxYear) continue;
    const position = scale.yearToPosition(year);
    const previous = groups.at(-1);
    if (previous && (position - previous.position) * width < gap) previous.events.push(event);
    else groups.push({ position, events: [event] });
  }
  return groups;
}

export function groupDate(events: readonly HistoricalEvent[]): string {
  const first = events[0], last = events.at(-1);
  if (!first || !last) return '';
  if (events.length === 1) return formatEventDate(first);
  const start = eventStartYear(first), end = eventStartYear(last);
  return start === end ? formatYear(start) : `${formatYear(start)} – ${formatYear(end)}`;
}
