// The compact reading sheet supports a swipe on its handle or heading and a keyboard toggle.
export const MOBILE_QUERY = '(max-width: 1023px)';
export const isMobileLayout = (): boolean => window.matchMedia(MOBILE_QUERY).matches;
export type SheetState = 'peek' | 'full';

function stops(panel: HTMLElement) {
  const viewport = window.visualViewport?.height ?? window.innerHeight;
  const bottom = Number.parseFloat(getComputedStyle(panel).bottom) || 0;
  const header = document.querySelector('.topbar')?.getBoundingClientRect().bottom ?? 0;
  const full = Math.max(100, Math.floor(viewport - bottom - header - 10));
  const peek = Math.min(full, Math.max(118, Math.min(188, Math.round(viewport * .215), Math.round(full * .54))));
  panel.style.setProperty('--sheet-peek', peek + 'px');
  panel.style.setProperty('--sheet-full', full + 'px');
  return { peek, full };
}

export function setSheetState(panel: HTMLElement, state: SheetState): void {
  if (isMobileLayout()) stops(panel);
  panel.dataset.sheet = state;
  panel.style.height = '';
  panel.querySelector('.panel__grab')?.setAttribute('aria-expanded', String(state === 'full'));
}

export function attachSheet(panel: HTMLElement, grab: HTMLElement, close: () => void): void {
  setSheetState(panel, 'peek');
  const resize = (): void => { if (isMobileLayout()) stops(panel); };
  window.addEventListener('resize', resize);
  window.visualViewport?.addEventListener('resize', resize);
  const chrome = new ResizeObserver(resize);
  for (const node of document.querySelectorAll('.topbar, #timeline')) chrome.observe(node);

  let gesture: { id: number; y: number; time: number; height: number; state: SheetState; full: number; peek: number } | null = null;
  let dragging = false;
  let suppressClick = false;

  panel.addEventListener('pointerdown', (e) => {
    if (!isMobileLayout() || !e.isPrimary || e.button !== 0 || gesture || !(e.target instanceof Element)) return;
    if (!e.target.closest('.panel__grab, .place-heading, .card__meta')) return;
    if (e.target.closest('a,button,input,select') && !grab.contains(e.target)) return;
    suppressClick = false;
    dragging = false;
    gesture = { id: e.pointerId, y: e.clientY, time: e.timeStamp, height: panel.offsetHeight,
      state: panel.dataset.sheet === 'full' ? 'full' : 'peek', ...stops(panel) };
    // Capture on the handle itself when pressed, so an ordinary tap still activates its button.
    const surface = grab.contains(e.target) ? grab : panel;
    surface.setPointerCapture(e.pointerId);
  });
  panel.addEventListener('pointermove', (e) => {
    if (gesture?.id !== e.pointerId) return;
    const dy = gesture.y - e.clientY;
    if (!dragging && Math.abs(dy) < 5) return;
    dragging = true;
    panel.classList.add('is-dragging');
    panel.style.height = Math.max(58, Math.min(gesture.full, gesture.height + dy)) + 'px';
  });
  const release = (e: PointerEvent): void => {
    if (!gesture || e.pointerId !== gesture.id) return;
    const start = gesture;
    gesture = null;
    const height = panel.offsetHeight;
    panel.classList.remove('is-dragging');
    if (!dragging) return;
    dragging = false;
    suppressClick = true;
    if (e.type !== 'pointerup') { setSheetState(panel, start.state); return; }
    const dy = e.clientY - start.y;
    const flick = Math.abs(dy) >= 25 && Math.abs(dy) / Math.max(1, e.timeStamp - start.time) > .48;
    if (start.state === 'peek' && dy > 0 && (flick || height < start.peek * .67)) {
      setSheetState(panel, 'peek'); close(); return;
    }
    const next = flick ? (dy < 0 ? 'full' : 'peek') : height > (start.peek + start.full) / 2 ? 'full' : 'peek';
    setSheetState(panel, next);
  };
  for (const type of ['pointerup', 'pointercancel', 'lostpointercapture'] as const) panel.addEventListener(type, release);
  grab.addEventListener('click', (e) => {
    if (suppressClick && e.detail !== 0) { suppressClick = false; return; }
    setSheetState(panel, panel.dataset.sheet === 'full' ? 'peek' : 'full');
  });
}

/** Keeps Tab inside the panel (call from a keydown listener while the sheet is open on mobile). */
export function trapFocus(panel: HTMLElement, event: KeyboardEvent): void {
  if (event.key !== 'Tab') return;
  const focusable = [
    ...panel.querySelectorAll<HTMLElement>('a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])'),
  ].filter((node) => node.offsetParent !== null);
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (!first || !last) return;
  const active = document.activeElement;
  if (event.shiftKey && (active === first || !panel.contains(active))) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && (active === last || !panel.contains(active))) {
    event.preventDefault();
    first.focus();
  }
}
