import story from './instruments/story.webp';
import follow from './instruments/follow.webp';
import film from './instruments/film.webp';
import sources from './instruments/sources.webp';
import filters from './instruments/filters.webp';
import myths from './instruments/myths.webp';
import home from './instruments/home.webp';
import dice from './instruments/dice.webp';
import zoom from './instruments/zoom.webp';

const instruments = { story, follow, film, sources, filters, myths, home, dice, zoom };

export function instrumentImage(name: string): string | undefined {
  return Object.hasOwn(instruments, name) ? instruments[name as keyof typeof instruments] : undefined;
}

