// The scrubber: a track with a draggable handle that is a proper role="slider".
// Pointer (mouse and touch) and keyboard input both report a year through onInput; pointer
// updates are throttled to one per animation frame so the map stays smooth.

import { attachScrubGesture } from './scrubGesture.ts';
import { createScrubLens } from './scrubLens.ts';
import { fineYear } from './lensScale.ts';
import type { Scale } from './scale.ts';

export interface SliderOptions {
  scale: Scale;
  /** The user asked for a specific year. */
  onInput(year: number): void;
  /** The user took control (pointer down or key press), so playback should pause. */
  onUserControl(): void;
  onScrubChange(active: boolean): void;
  checkpoints(): ReadonlySet<number>;
  onFineCommit(year: number): void;
}

export interface Slider {
  /** Shared gesture surface for the ruler and its dated buttons. */
  spine: HTMLElement;
  /** Pointer target; contains the rail, ticks and handle. */
  element: HTMLElement;
  /** Positioned container for ticks (same width as the rail). */
  inner: HTMLElement;
  /** Swap the mapping between track position and years (the era-zoomed timeline). */
  setScale(next: Scale): void;
  handle: HTMLElement;
  setYear(year: number, valueText: string): void;
}

export function createSlider({ scale: initialScale, onInput, onUserControl, onScrubChange, checkpoints, onFineCommit }: SliderOptions): Slider {
  let scale = initialScale;
  const element = document.createElement('div');
  element.className = 'track';
  const spine = document.createElement('div');
  spine.className = 'chronicle-spine';
  spine.append(element);

  const inner = document.createElement('div');
  inner.className = 'track__inner';

  const rail = document.createElement('div');
  rail.className = 'track__rail';

  const handle = document.createElement('div');
  handle.className = 'handle';
  handle.tabIndex = 0;
  handle.setAttribute('role', 'slider');
  handle.setAttribute('aria-label', 'Year');
  handle.setAttribute('aria-orientation', 'horizontal');
  handle.setAttribute('aria-valuemin', String(scale.minYear));
  handle.setAttribute('aria-valuemax', String(scale.maxYear));
  const knob = document.createElement('span');
  knob.className = 'handle__knob';
  handle.append(knob);

  inner.append(rail, handle);
  element.append(inner);

  const lens = createScrubLens(inner, rail, () => scale, checkpoints);
  let keyboardFine = false;
  const closeFine = (): void => {
    if (!keyboardFine) return;
    keyboardFine = false; lens.close(); onScrubChange(false);
  };
  const atHandle = (year: number): number => {
    const rect = inner.getBoundingClientRect();
    return rect.left + scale.yearToPosition(year) * rect.width;
  };
  handle.setAttribute('aria-keyshortcuts', 'Space Enter Escape ArrowLeft ArrowRight');
  handle.addEventListener('blur', closeFine);
  element.addEventListener('pointerdown', closeFine, true);
  attachScrubGesture(spine, element, inner, handle, lens, { scale: () => scale, onInput, onUserControl, onScrubChange, onFineCommit });

  // Keyboard: arrows step one local unit, Shift (or PageUp/PageDown) takes ten, Home/End jump.
  handle.addEventListener('keydown', (e) => {
    if (e.altKey || e.ctrlKey || e.metaKey) return;
    const current = Number(handle.getAttribute('aria-valuenow'));
    if (e.key === ' ' || (keyboardFine && (e.key === 'Enter' || e.key === 'Escape'))) {
      e.preventDefault(); e.stopPropagation();
      if (keyboardFine) {
        closeFine();
        if (e.key !== 'Escape') onFineCommit(current);
      } else {
        keyboardFine = true; onUserControl(); onScrubChange(true);
        const x = atHandle(current);
        lens.begin(current, x); lens.lock(current, x);
      }
      return;
    }
    const big = e.shiftKey;
    let next: number | null = null;
    switch (e.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        next = keyboardFine ? fineYear(current, big ? 10 : 1, 1, scale) : scale.stepYear(current, 1, big);
        break;
      case 'ArrowLeft':
      case 'ArrowDown':
        next = keyboardFine ? fineYear(current, big ? -10 : -1, 1, scale) : scale.stepYear(current, -1, big);
        break;
      case 'PageUp':
        next = scale.stepYear(current, 1, true);
        break;
      case 'PageDown':
        next = scale.stepYear(current, -1, true);
        break;
      case 'Home':
        next = scale.minYear;
        break;
      case 'End':
        next = scale.maxYear;
        break;
      default:
        return;
    }
    e.preventDefault();
    onUserControl();
    onInput(next);
    if (keyboardFine) lens.show(next, atHandle(next));
  });

  return {
    spine,
    element,
    inner,
    handle,
    setScale(next) {
      scale = next;
      handle.setAttribute('aria-valuemin', String(scale.minYear));
      handle.setAttribute('aria-valuemax', String(scale.maxYear));
    },
    setYear(year, valueText) {
      handle.style.left = `${scale.yearToPosition(year) * 100}%`;
      handle.setAttribute('aria-valuenow', String(year));
      handle.setAttribute('aria-valuetext', valueText);
    },
  };
}
