// A keyboard shortcuts list: press ? anywhere (outside a text field) or use the About dialog.
// Only shortcuts that really exist are listed; keep this in step with search/index.ts,
// timeline/slider.ts, story/overlay.ts and escape.ts.

import { el } from './dom.ts';

const ROWS: readonly (readonly [keys: readonly string[], what: string])[] = [
  [['/'], 'Focus the search box'],
  [['←', '→'], 'With the timeline handle focused: move the year one step'],
  [['Shift', '← →'], 'Move the year ten steps (PageUp and PageDown do the same)'],
  [['Home', 'End'], 'Jump to the first or last year'],
  [['←', '→'], 'Inside a guided story: the previous or next step'],
  [['Esc'], 'Close the open panel, card, filter list or tour'],
  [['?'], 'Show this list'],
];

let dialog: HTMLDialogElement | null = null;

function build(): HTMLDialogElement {
  const node = el('dialog', 'about shortcuts');
  node.setAttribute('aria-labelledby', 'shortcuts-title');
  const title = el('h2', 'about__title', 'Keyboard shortcuts');
  title.id = 'shortcuts-title';

  const list = el('dl', 'shortcuts__list');
  for (const [keys, what] of ROWS) {
    const dt = el('dt', 'shortcuts__keys');
    keys.forEach((key, i) => {
      if (i > 0) dt.append(' ');
      dt.append(el('kbd', '', key));
    });
    list.append(dt, el('dd', 'shortcuts__what', what));
  }

  const close = el('button', 'btn btn--primary', 'Close');
  close.type = 'button';
  close.addEventListener('click', () => node.close());
  node.addEventListener('click', (event) => {
    if (event.target === node) node.close();
  });
  node.append(title, list, close);
  document.body.append(node);
  return node;
}

export function openShortcuts(): void {
  dialog ??= build();
  if (!dialog.open) dialog.showModal();
}

function isTyping(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return target.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName);
}

/** Opens the list on "?" (Shift + /), unless the reader is typing or another dialog is open. */
export function initShortcuts(): void {
  document.addEventListener('keydown', (e) => {
    if (e.key !== '?' || e.ctrlKey || e.metaKey || e.altKey || e.defaultPrevented) return;
    if (isTyping(e.target) || document.querySelector('dialog[open]')) return;
    e.preventDefault();
    openShortcuts();
  });
}
