// The Nakba counter: how many villages and towns in the data had been depopulated by the
// current year, climbing as the reader scrubs across 1947-1949. Counts the places whose
// `depopulated` year is set (sourced from their own cards); hidden before the first one.

import { formatYear } from '../data/format.ts';
import type { Place } from '../data/placeTypes.ts';
import { el } from '../dom.ts';
import { getState, subscribe } from '../state.ts';

export function initNakbaCounter(container: HTMLElement, places: readonly Place[]): void {
  const years = places
    .flatMap((p) => (p.depopulated === undefined ? [] : [p.depopulated]))
    .sort((a, b) => a - b);
  const head = years[0];
  if (head === undefined) return;
  const first: number = head;
  const total = years.length;

  const chip = el('div', 'nakba-counter');
  chip.title =
    'Villages and towns in this map depopulated by the chosen year, from the entries of Walid Khalidi, All That Remains, and Palestine Remembered. Each has its own place card; the year is approximate for some.';
  const num = el('strong', 'nakba-counter__n');
  const text = el('span', 'nakba-counter__text');
  chip.append(num, text);
  chip.hidden = true;

  const live = el('span', 'sr-only');
  live.setAttribute('role', 'status');
  live.setAttribute('aria-live', 'polite');
  chip.append(live);

  (container.querySelector('.tl-side') ?? container).prepend(chip);

  let liveTimer = 0;
  function update(): void {
    const year = getState().currentYear;
    if (year < first) {
      chip.hidden = true;
      return;
    }
    // `years` is sorted, so the count of years up to `year` is a binary search, not a scan.
    let low = 0;
    let high = years.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if ((years[mid] ?? Infinity) <= year) low = mid + 1;
      else high = mid;
    }
    const count = low;
    num.textContent = count.toLocaleString('en-US');
    text.textContent = ` of ${total.toLocaleString('en-US')} villages depopulated by ${formatYear(year, true)}`;
    chip.hidden = false;
    window.clearTimeout(liveTimer);
    liveTimer = window.setTimeout(() => {
      live.textContent = `${count} of ${total} villages depopulated by ${formatYear(getState().currentYear, true)}`;
    }, 600);
  }

  update();
  subscribe((state, previous) => {
    if (state.currentYear !== previous.currentYear) update();
  });
}
