import { HOME_BOUNDS } from '../data/region.ts';
import type { LngLatBox } from '../data/region.ts';
import type { EventLocation } from '../data/types.ts';
import type { ResolvedPath } from '../data/pathTypes.ts';
import { curveThrough } from '../paths/geometry.ts';
import type { Pos } from '../paths/geometry.ts';

/** Only locations explicitly describing the land as a whole use the home composition. */
export function isLandEvent(location: EventLocation): boolean {
  return location.precision === 'approximate' &&
    (/\bcountry-wide\b/i.test(location.name) ||
      /^(?:Mandatory |Western )?Palestine(?:$| \((?:region\)|adopted |decided |proclaimed |held ))/i.test(location.name));
}

export function pathPositions(path: ResolvedPath): Pos[] {
  return path.shape === 'traced' && path.line.length >= 2 ? path.line :
    curveThrough(path.waypoints.map(p => [p.lng, p.lat]));
}

export function sceneBounds(location: EventLocation, paths: readonly ResolvedPath[]): LngLatBox | undefined {
  if (isLandEvent(location)) return HOME_BOUNDS;
  if (!paths.length) return undefined;
  const points = paths.flatMap(pathPositions);
  if (!points.length) return undefined;
  const xs = points.map(p => p[0]), ys = points.map(p => p[1]);
  return [[Math.min(...xs), Math.min(...ys)], [Math.max(...xs), Math.max(...ys)]];
}
