// A faint survey-sheet graticule: half-degree latitude and longitude lines across the
// frame, like the grid printed on the 1940s Survey of Palestine sheets. Drawn from the
// frame bounds; no labels, just the lines at low opacity.

import type { LayerSpecification, SourceSpecification } from 'maplibre-gl';
import { frameBounds } from '../data/frame.ts';
import { withAlpha } from './color.ts';
import type { Palette } from './style.ts';

export const GRATICULE_SOURCE = 'graticule';
const LAYER = 'look-graticule';
const STEP = 0.5;

export function graticuleSource(): SourceSpecification {
  const [[west, south], [east, north]] = frameBounds();
  const lines: { type: 'Feature'; properties: Record<string, never>; geometry: { type: 'LineString'; coordinates: [number, number][] } }[] = [];
  for (let lon = Math.ceil(west / STEP) * STEP; lon <= east; lon += STEP) {
    lines.push({
      type: 'Feature',
      properties: {},
      geometry: { type: 'LineString', coordinates: [[lon, south], [lon, north]] },
    });
  }
  for (let lat = Math.ceil(south / STEP) * STEP; lat <= north; lat += STEP) {
    lines.push({
      type: 'Feature',
      properties: {},
      geometry: { type: 'LineString', coordinates: [[west, lat], [east, lat]] },
    });
  }
  return { type: 'geojson', data: { type: 'FeatureCollection', features: lines } };
}

function lineColor(p: Palette): string {
  return withAlpha(p.ink, 0.08);
}

export function graticuleLayer(p: Palette): LayerSpecification {
  return {
    id: LAYER,
    type: 'line',
    source: GRATICULE_SOURCE,
    paint: { 'line-color': lineColor(p), 'line-width': 0.8 },
  } as LayerSpecification;
}

/** Paint values to re-apply on a theme change, or null if the id is not ours. */
export function graticulePaintFor(id: string, p: Palette): Record<string, unknown> | null {
  return id === LAYER ? { 'line-color': lineColor(p) } : null;
}
